INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8466', 'spa', 'campamento, lugar de acampar (posiblemente texto corrupto; BDB sugiere leer ''os esconderéis'' en su lugar)', 'Este sustantivo aparece únicamente en 2 Reyes 6:8, en una frase que ha desconcertado a los intérpretes. BDB señala que la forma es «muy extraña» y sugiere corrupción textual, proponiendo leer en su lugar «os esconderéis» basándose en la versión siríaca. Si el sustantivo es original, derivaría de la raíz que significa «acampar» e indicaría el lugar donde alguien establece su campamento. El contexto narrativo de Eliseo, que describe movimientos militares, admite ambas lecturas: ya sea que Eliseo conoce dónde acampará el enemigo o dónde se esconderá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8467', 'spa', 'Súplica, ruego de misericordia; también el favor o la gracia misericordiosa que se busca', 'Súplica, ruego de misericordia; también el favor o la gracia misericordiosa que se busca');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8468', 'spa', 'Tejina, nombre propio: descendiente de Judá mencionado en las listas genealógicas (1 Crónicas 4:12)', 'Nombre propio que aparece en las genealogías de Judá en 1 Crónicas 4:12. El nombre posiblemente deriva de la raíz hebrea que significa «súplica» o «gracia», lo que lo convierte en un nombre significativo dado al nacer. Tales nombres eran frecuentes en las familias de Judá y solían reflejar las circunstancias del nacimiento o las oraciones de los padres. Su ubicación genealógica sugiere una figura menor cuya importancia principal reside en la preservación de los registros del linaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8469', 'spa', 'Súplicas, ruegos fervientes de misericordia — peticiones sinceras dirigidas a Dios o a un superior implorando gracia.', 'Súplicas, ruegos fervientes de misericordia — peticiones sinceras dirigidas a Dios o a un superior implorando gracia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8470', 'spa', 'el tajanita, gentilicio con artículo: designación de clan en el censo tribal de Efraín (Números 26:35)', 'Este término gentilicio aparece en el censo de Números 26, identificando un clan dentro de la tribu de Efraín descendiente de Taján. El artículo hace que funcione como sustantivo colectivo, «los tajanitas», refiriéndose a todos los miembros de este grupo familiar. Tales designaciones censales eran fundamentales para la distribución de tierras y la organización tribal durante el período de la conquista. El nombre preserva uno de varios clanes efraimitas que rastreaban su linaje a través de la línea de José.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8471', 'spa', 'Tajpanjés: ciudad egipcia fronteriza en el delta oriental del Nilo adonde huyeron los refugiados judíos tras la caída de Jerusalén.', 'Nombre de una ciudad fronteriza egipcia, identificada con la antigua Dafne (actual Tell Defenneh), ubicada en el delta oriental del Nilo, a unos veintinueve kilómetros al sureste de Tanis. Tajpanjés aparece casi exclusivamente en las profecías de Jeremías como destino de los refugiados judíos que huyeron a Egipto desobedeciendo la advertencia profética tras la caída de Jerusalén en el 586 a.C. Jeremías mismo fue llevado allí (Jer 43:7-9) y profetizó que Nabucodonosor pondría su trono a sus puertas (Jer 43:8-13). También aparece en Jeremías 2:16 y en Ezequiel 30:18, que anuncia su oscurecimiento bajo el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8472', 'spa', 'Tajpenes (nombre propio: reina egipcia, cuñada del Faraón)', 'Tajpenes fue una reina egipcia durante el reinado temprano de Salomón, hermana del Faraón que dio asilo a Hadad el edomita, rival de Jeroboam. 1 Reyes 11:19-20 relata que el Faraón dio a Hadad a la hermana de Tajpenes como esposa, y Tajpenes misma crió a su hijo Genubat en la casa del Faraón entre los príncipes. El nombre es egipcio, mostrando la variación estándar de transliteración griega. Tajpenes representa la generosidad real egipcia hacia refugiados que más tarde podrían servir intereses políticos egipcios—Hadad eventualmente regresó para causar problemas a Salomón. Su papel como madre adoptiva de Genubat sugiere su alto estatus en el palacio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8475', 'spa', 'Tajrea (con conjunción), nombre propio: descendiente de Saúl en la genealogía benjaminita (1 Crónicas 9:41)', 'Nombre propio que aparece en la genealogía del rey Saúl en 1 Crónicas 9:41, con una forma paralela (Tarea) en 1 Crónicas 8:35. La variación entre ambas formas ilustra las diferencias escribales habituales en la transmisión de genealogías. Como descendiente de Saúl, esta figura pertenece a la línea real benjaminita, aunque aparece en el período postexílico dentro del interés de Crónicas por preservar la continuidad genealógica de Israel. Las versiones de la Septuaginta presentan variantes adicionales de transliteración, algo típico en nombres sin etimología clara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8476', 'spa', 'Animal marino (dugongo, marsopa o foca) cuya piel resistente se usaba para la cubierta exterior del tabernáculo. Un animal apreciado en el antiguo Cer', 'Animal marino (dugongo, marsopa o foca) cuya piel resistente se usaba para la cubierta exterior del tabernáculo. Un animal apreciado en el antiguo Cercano Oriente por su cuero duradero; el tachash proporcionaba la capa protectora más externa del tabernáculo. La mayoría de los eruditos modernos lo identifican con el dugongo o la marsopa del Mar Rojo, aunque las versiones antiguas sugirieron tejón o cuero de color jacinto. Las traducciones al español lo vierten como ''tejón'', mientras que el francés opta por ''marsouin'' (marsopa), reflejando siglos de incertidumbre. En Ezequiel 16:10, Dios recuerda haber calzado a Jerusalén con sandalias de cuero de tachash, un detalle que eleva el material de la mera utilidad a símbolo de espléndido cuidado divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8477', 'spa', 'Tajás, nombre propio: hijo de Nacor y Reumá, sobrino de Abraham (Génesis 22:24)', 'Este nombre propio pertenece a uno de los hijos de Nacor con su concubina Reumá, lo que lo convierte en sobrino de Abraham. El nombre ha atraído la atención académica porque podría preservar una conexión con una región del norte de Siria mencionada en fuentes egipcias. Algunos estudiosos lo identifican con Tijes, un lugar al norte de Cades junto al río Orontes. Esto encajaría con el interés de Génesis 22 en establecer las conexiones familiares extendidas de Abraham en la región aramea, proporcionando un trasfondo genealógico para las narrativas posteriores sobre los parientes de Abraham en Harán y sus alrededores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8478', 'spa', 'Debajo de, bajo (espacial); en lugar de, en vez de (sustitución); porque, por cuanto (causal).', 'Derivado de un sustantivo que significa ''la parte inferior,'' תַּחַת funciona principalmente como preposición con tres sentidos distintos que se despliegan a partir de una sola imagen espacial. En su uso más concreto, sitúa algo físicamente debajo de otra cosa (Gn 18:4, sentado bajo un árbol). Por extensión natural pasa a significar ''en lugar de,'' expresando sucesión o intercambio: Salomón reina תַּחַת David (1 R 1:30), o el carnero es ofrecido תַּחַת Isaac (Gn 22:13). En la rara construcción תַּחַת אֲשֶׁר se convierte en conjunción causal con el sentido de ''porque.'' Las glosas en español y francés reflejan fielmente estos desplazamientos: ''bajo'' para lo espacial, ''en lugar de'' para lo sustitutivo y ''porque'' para lo causal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8479', 'spa', 'debajo de, bajo (preposición aramea con sufijo, equivalente en arameo bíblico del hebreo תַּחַת)', 'El equivalente arameo del hebreo ''debajo de''; esta preposición aparece en las secciones arameas de Daniel para describir relaciones espaciales y de subordinación. Comparte cognados con otros dialectos arameos (targúmico, siríaco, palmireno) y funciona de manera idéntica a su contraparte hebrea. Daniel la emplea tanto en sentido literal (debajo del árbol) como metafórico (debajo del cielo = en toda la tierra). Las formas con sufijos pronominales muestran la morfología aramea estándar, a veces con vocalización hebraizada en la tradición masorética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8480', 'spa', 'Tajat (Tachat): nombre levítico, nombre efrateo y estación en el desierto.', 'Nombre propio que aparece en listas genealógicas e itinerarios del desierto. Como nombre personal, Tajat designa tanto a un levita del linaje de Coat (1 Cr 6:24, 37) como a un ancestro efraimita (1 Cr 7:20, donde el nombre aparece dos veces en la genealogía). Como topónimo, identifica una parada en las peregrinaciones de Israel por el desierto (Nm 33:26-27). El nombre probablemente derive de la palabra hebrea común que significa ''debajo, bajo'', aunque en estos contextos funciona puramente como identificador. Las traducciones al francés y al alemán curiosamente vierten el nombre personal con el sustantivo común ''sous/unter'' (debajo), reflejando la conexión etimológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8481', 'spa', 'Inferior o el más bajo en posición; adjetivo espacial para niveles arquitectónicos, rasgos geográficos y elevación relativa. Un adjetivo posicional qu', 'Inferior o el más bajo en posición; adjetivo espacial para niveles arquitectónicos, rasgos geográficos y elevación relativa. Un adjetivo posicional que marca lo que se encuentra debajo o en la parte más baja: el piso inferior, la piscina inferior, el asentamiento bajo. En el templo de Salomón identifica el nivel más bajo de las cámaras laterales (1 R 6:6, 8), y Ezequiel lo usa para el pavimento inferior y el reborde inferior del altar (Ez 40:18-19; 43:14). Isaías menciona la ''piscina inferior'' del sistema hídrico de Jerusalén (Is 22:9). Su uso geográfico más frecuente aparece en el topónimo compuesto Bet-horón de abajo (Jos 16:3; 18:13; 1 Cr 7:24; 2 Cr 8:5), distinguiendo el pueblo bajo de su contraparte superior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8482', 'spa', 'Partes más bajas, profundidades de la tierra (Seol/inframundo); inferior (comparativo, de cámaras o piedras); base o fondo de un accidente geográfico.', 'Partes más bajas, profundidades de la tierra (Seol/inframundo); inferior (comparativo, de cámaras o piedras); base o fondo de un accidente geográfico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8484', 'spa', 'Del medio — adjetivo posicional que describe el piso central de un edificio o la posición intermedia en una serie', 'El adjetivo תִּיכוֹן (tikon) significa ''del medio'' o ''central'', ubicando algo entre dos extremos en una serie espacial. Su uso arquitectónico más destacado describe el piso intermedio del Templo de Salomón (1 R 6:6, 8), donde una estructura lateral de tres niveles rodeaba la sala principal. La barra central que atravesaba el centro de los bastidores del tabernáculo (Ex 26:28; 36:33) es su otro referente clave. El ataque nocturno de Gedeón durante la ''vigilia de en medio'' (Jue 7:19) extiende el término a la división temporal. Ezequiel lo emplea también para el nivel intermedio de las cámaras del templo visionario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8485', 'spa', 'Tema — territorio árabe y su pueblo, descendiente de Ismael', 'Tema designa un asentamiento oasis en el noroeste de Arabia, identificado con la moderna Teyma, y la tribu descendiente del hijo de Ismael del mismo nombre (Gn 25:15). Isaías 21:14 exhorta a los habitantes de Tema a llevar agua al sediento, reflejando su papel como parada de caravanas. Jeremías 25:23 agrupa a Tema con Dedán y Buz entre los pueblos árabes bajo juicio divino. Job 6:19 invoca las caravanas de Tema como metáfora de esperanza frustrada, pues los viajeros del desierto dependen de wadis estacionales que pueden secarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8486', 'spa', 'Sur, la dirección o región meridional; también el viento del sur', 'Sur, la dirección o región meridional; también el viento del sur');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8487', 'spa', 'Temán — región o ciudad en Edom, asociada con tradiciones sapienciales y oráculos proféticos de juicio', 'El nombre propio תֵּימָן (Temán) designa una región o ciudad en el norte de Edom, vinculada tradicionalmente a Temán, hijo de Elifaz y nieto de Esaú (Gn 36:11, 15, 42). Temán era célebre por sus sabios, reputación reflejada en la pregunta retórica de Jeremías: «¿Ya no hay sabiduría en Temán?» (Jer 49:7). Elifaz el temanita, el interlocutor más destacado de Job, proviene de esta tradición. Los profetas dirigen oráculos contra Temán como representante de Edom (Jer 49:7, 20; Ez 25:13; Am 1:12; Abd 9). En Habacuc 3:3, Dios viene «desde Temán» en una marcha teofánica que evoca las tradiciones del Sinaí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8488', 'spa', 'Temeni, nombre propio: descendiente de Judá en la genealogía tribal (1 Crónicas 4:6)', 'Nombre propio que aparece en las genealogías de Judá en 1 Crónicas 4:6. Posiblemente derive de la raíz que significa ''sureño'' o esté relacionado con la región de Temán, lo que sugiere un origen geográfico. Crónicas preserva muchos nombres cuya función principal es mantener la red genealógica que conectaba a los judíos postexílicos con su herencia tribal. Sin contexto narrativo adicional, conocemos a este individuo únicamente como un eslabón en el árbol familiar de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8489', 'spa', 'El temanita: gentilicio que identifica a una persona de Temán en Edom, usado casi exclusivamente como epíteto de Elifaz, amigo de Job.', 'Adjetivo gentilicio que significa «el temanita», derivado del topónimo Temán, un distrito en el norte de Edom célebre por su tradición sapiencial (cf. Jer 49:7; Abd 1:9). En el uso bíblico, el término aparece casi exclusivamente como epíteto fijo de Elifaz, el primero y más prominente de los tres amigos de Job (Job 2:11; 4:1; 15:1; 22:1; 42:7, 9). Fuera de Job, aparece en Génesis 36:34 y 1 Crónicas 1:45 describiendo la tierra natal de Husam como «la tierra de los temanitas». El artículo definido constante lo marca como designación reconocida y no mera nota geográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8491', 'spa', 'el tizita, gentilicio con artículo: designación de clan o región de uno de los guerreros de David (1 Crónicas 11:45)', 'Este adjetivo gentilicio identifica a uno de los valientes de David en 1 Crónicas 11:45, aunque el lugar o clan al que hace referencia es desconocido. El término no aparece en ningún otro pasaje bíblico, y aun los intérpretes antiguos lo encontraron oscuro. Probablemente designa un pueblo de origen, un territorio de clan o un grupo familiar que tenía importancia local pero no perduró en la memoria histórica más amplia. Estas designaciones eran esenciales para distinguir a los guerreros en los registros militares cuando los nombres personales por sí solos podían resultar ambiguos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8492', 'spa', 'Mosto, vino nuevo — jugo de uva recién prensado, enumerado junto al grano y el aceite como signo de bendición agrícola.', 'Mosto, vino nuevo — jugo de uva recién prensado, enumerado junto al grano y el aceite como signo de bendición agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8493', 'spa', 'Tirya, nombre propio: hijo de Jehallelel en la genealogía de Judá (1 Crónicas 4:16)', 'Nombre propio que aparece en las genealogías de Judá en 1 Crónicas 4:16. Algunos manuscritos muestran variantes (Tirya frente a Tirea), lo que refleja la transmisión fluida de los textos genealógicos. El nombre podría derivar de la raíz que significa ''temor'' o ''reverencia'', convirtiéndolo posiblemente en un nombre teofórico que expresa piedad. Como muchos nombres en las genealogías de Crónicas, preserva la memoria familiar sin ofrecer detalles narrativos, cumpliendo el propósito del Cronista de establecer registros tribales exhaustivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8495', 'spa', 'macho cabrío, cabrón; cabra macho usada como ganado valioso y símbolo de porte altivo', 'Término que designa específicamente al macho de la cabra, distinguiéndolo de las hembras (עִזִּים) en Génesis 32:14. Aparece en contextos de riqueza ganadera y tributo real: Josafat recibía miles de carneros y machos cabríos como tributo (2 Cr 17:11), y Jacob separó los machos manchados y moteados de los rebaños de Labán (Gn 30:35). Proverbios 30:31 lo incluye entre las criaturas que caminan con porte majestuoso. El vocablo se emplea en hebreo, arameo y árabe con significado consistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8496', 'spa', 'opresión, daño, violencia (maltrato infligido por los poderosos)', 'Este sustantivo denota opresión, daño o violencia infligida a los vulnerables. Aparece en los Salmos emparejado con otros términos para maldad. Salmo 10:7 describe la boca del malvado llena de maldición, engaño y ''opresión.'' Salmo 55:11 retrata las calles de Jerusalén donde ''la opresión y el engaño no se apartan.'' Salmo 72:14 promete que el rey ideal redimirá vidas ''de la opresión y la violencia'' (el texto puede incluir ''violencia'' como glosa). Proverbios 29:13 menciona ''al opresor'' (literalmente ''hombre de opresiones'') a quien Dios juzgará. El término enfatiza el abuso de poder y el daño hecho a quienes no tienen recurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8497', 'spa', 'ser conducido, reunido, congregado (significado incierto; forma Pual que sugiere acción pasiva)', 'Este verbo aparece únicamente en Deuteronomio 33:3 dentro de un versículo notoriamente difícil, y su significado sigue siendo disputado. La forma Pual sugiere un sentido pasivo: algo hecho al sujeto. El contexto insinúa que Israel fue reunido, conducido o congregado a los pies de Dios para recibir enseñanza. Algunas traducciones proponen ''se postraron'', otras ''fueron conducidos'' o ''se congregaron''. La evidencia multilingüe muestra a los traductores luchando con la misma ambigüedad. La escena pertenece claramente a la bendición de Moisés, que describe la relación de Israel con la instrucción divina, pero el matiz preciso escapa a toda certeza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8499', 'spa', 'disposición, preparación, lugar fijo, morada (sustantivo que describe orden espacial o ubicación establecida)', 'Este sustantivo transmite la idea de algo dispuesto, preparado o establecido en su lugar. Aparece en contextos que describen disposición arquitectónica (el templo de Ezequiel), provisiones militares (Nahúm) y la morada de Dios (Job). La raíz sugiere fijeza y orden: algo firmemente asentado en su posición. En Job 23:3 funciona como paralelo de ''lugar'' (מָקוֹם) y se refiere a la morada o trono divino. La palabra enfatiza estabilidad y posición establecida, ya sea de estructuras físicas, recursos preparados o habitación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8501', 'spa', 'opresión, violencia, agravio (sustantivo que describe el daño infligido por los opresores)', 'Este sustantivo denota violencia opresiva o agravio, particularmente el infligido por quienes detentan poder. Aparece en paralelo con otros términos para violencia y engaño en los Salmos y Proverbios, pintando retratos de opresores malvados. Proverbios 29:13 lo emplea para caracterizar al ''hombre de opresiones'', aquel que usa la violencia para explotar a otros. La forma plural enfatiza actos repetidos o variados de opresión. La familia léxica incluye conceptos de daño e injusticia, centrándose en el perjuicio causado a los vulnerables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8502', 'spa', 'plenitud, perfección, consumación (sustantivo que describe el estado de ser completo o perfecto)', 'Este sustantivo denota el estado de plenitud o perfección, y aparece únicamente en el Salmo 119:96 en una profunda reflexión sobre los límites de la perfección terrenal. El salmista observa que incluso a ''toda perfección'' le ha visto fin —toda plenitud terrenal tiene límites—, pero el mandamiento de Dios es inmensamente amplio, ilimitado. La palabra deriva de la raíz que significa ''plenitud'' y representa el concepto de algo acabado, perfecto o integral. Capta la idea de algo llevado a su plena realización o consumación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8503', 'spa', 'Fin, límite, plenitud; el confín extremo o la extensión máxima de algo', 'Este sustantivo expresa la idea de alcanzar un límite final o la plenitud absoluta de algo. En Nehemías 3:21 marca un punto espacial: ''el fin de la casa de Eliasib.'' En Job se extiende hacia lo metafísico: ¿puede un mortal alcanzar ''el límite del Todopoderoso'' (11:7) o explorar ''todo confín remoto'' de la tierra (28:3)? El Salmo 139:22 gira hacia un sentido cualitativo — ''odio completo'' — donde la palabra funciona como intensificador adverbial, describiendo la totalidad absoluta de la oposición del salmista al mal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8504', 'spa', 'Azul/violeta — el preciado tinte y estambre azul-violeta utilizado en los textiles sagrados y el ajuar del tabernáculo. תְּכֵלֶת es el tinte azul-viol', 'Azul/violeta — el preciado tinte y estambre azul-violeta utilizado en los textiles sagrados y el ajuar del tabernáculo. תְּכֵלֶת es el tinte azul-violeta extraído del caracol marino múrex, uno de los colorantes más apreciados del mundo antiguo. Casi todas sus 49 apariciones se encuentran en Éxodo y Números en relación con el tabernáculo: las cortinas (Éx 26:1), el velo (26:31), el efod y el pectoral (28:6, 15), y el cordón que sujetaba la placa de oro al turbante (28:37). El color aparece casi siempre en la tríada sagrada de תְּכֵלֶת, אַרְגָּמָן (púrpura) y תוֹלַעַת שָׁנִי (escarlata), un trío que reaparece en las colgaduras del templo de 2 Crónicas 2-3 e incluso en la decoración del palacio de Ester 1:6. El único mandamiento no cultual es llamativo: cada israelita debía atar un hilo de תְּכֵלֶת a los flecos de su vestidura como recordatorio de guardar los mandamientos de Dios (Nm 15:38). La LXX lo traduce como hyakinthos (''jacinto''), señalando un matiz azul-violeta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8505', 'spa', 'Medir, pesar, evaluar; en Nifal, ser hallado recto o justo; en Piel, repartir o establecer firmemente.', 'Medir, pesar, evaluar; en Nifal, ser hallado recto o justo; en Piel, repartir o establecer firmemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8507', 'spa', 'Toquén (con conjunción), topónimo: ciudad en el territorio de Simeón (1 Crónicas 4:32)', 'Topónimo dentro del reparto territorial de Simeón, mencionado en 1 Crónicas 4:32. El nombre podría derivar de una raíz que significa ''medida'' o ''norma'', aunque su etimología permanece incierta. Como muchos asentamientos simeonitas, esta ciudad carece de otra atestación y su ubicación se ha perdido en la historia. Las variantes de la Septuaginta reflejan la incertidumbre de los traductores antiguos respecto al nombre. Sobrevive únicamente gracias a la cuidadosa preservación de las listas territoriales tribales en Crónicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8509', 'spa', 'manto, vestidura (con conjunción; prenda exterior fina, específicamente de lino y púrpura)', 'Este sustantivo designa un manto o vestidura exterior, y aparece en Ester 8:15 como parte del atuendo regio de Mardoqueo. El contexto especifica que está confeccionado de lino fino y púrpura, materiales asociados con la realeza y el alto rango en la corte persa. El término es raro, apareciendo solo aquí, y sugiere una prenda envuelta o enrollada (si es pertinente la raíz que significa ''enrollar''). Se trata de vestimenta palaciega que marca la elevación al honor, parte de la transformación visual que señala el vuelco en la suerte de Mardoqueo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8510', 'spa', 'Montículo, tell; colina artificial formada por los escombros acumulados de ciudades destruidas o antiguas', 'Un tel es el montículo característico que se forma cuando las ciudades del antiguo Cercano Oriente eran destruidas y reconstruidas repetidamente sobre el mismo emplazamiento, comprimiéndose cada capa en una colina elevada. Cuando Josué incendió Hai, esta se convirtió en ''un montículo para siempre'' (Jos 8:28), es decir, una ruina permanente. Deuteronomio 13:16 prescribe el mismo destino para una ciudad idólatra. Jeremías emplea el término tanto para la desolación (49:2, Rabá convertida en ''montón de ruinas'') como para la restauración (30:18, una ciudad reconstruida ''sobre su colina''), mostrando la concreción arqueológica de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8513', 'spa', 'fatiga, penalidad, angustia; agotamiento causado por opresión o adversidad prolongada', 'Este sustantivo expresa el desgaste acumulado del sufrimiento prolongado: las penalidades que Israel soportó bajo la esclavitud egipcia (Nm 20:14), las pruebas del peregrinaje por el desierto (Éx 18:8) y el peso de la opresión babilónica (Neh 9:32). Lamentaciones 3:5 lo emplea para describir las condiciones del asedio con intensidad extraordinaria. La forma relacionada מַתְּלָאָה aparece en Malaquías 1:13 para referirse al deber religioso vivido como carga tediosa. Las traducciones multilingües destacan tanto el agotamiento físico como la dificultad circunstancial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8514', 'spa', 'sequía, aridez extrema (plural intensivo que enfatiza la severidad de las condiciones desérticas)', 'Este sustantivo describe una sequía extrema, apareciendo en Oseas 13:5 para caracterizar el desierto donde Dios conoció a Israel. La forma plural es intensiva, subrayando la severidad total de las condiciones de aridez. Evoca el páramo reseco e implacable de las peregrinaciones de Israel por el desierto, donde la supervivencia dependía enteramente de la provisión divina. El término no solo transmite la ausencia de agua, sino la sequedad abrasadora que hace del desierto un lugar mortal, resaltando el conocimiento íntimo que Dios tenía de Israel en su condición más vulnerable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8516', 'spa', 'vestidura, indumentaria (sustantivo para ropa, usado metafóricamente para la armadura divina de venganza)', 'Este sustantivo designa la vestidura o indumentaria, apareciendo únicamente en Isaías 59:17 en una metáfora impactante. El profeta describe a Dios vistiéndose con ''ropas de venganza como vestidura,'' preparándose para la batalla en favor de Israel. La imagen se nutre de la iconografía guerrera del antiguo Cercano Oriente, donde dioses y reyes se revestían de armadura para el combate. Aquí la vestidura de Dios incluye justicia como coraza y salvación como yelmo, completando una armadura divina integral que subraya la plenitud de su preparación para el juicio y la liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8517', 'spa', 'nieve (sustantivo arameo, equivalente en arameo bíblico del hebreo שֶׁלֶג)', 'La palabra aramea para nieve, cognada del hebreo שֶׁלֶג y de equivalentes siríacos. Aparece en Daniel 7:9 en la visión del trono, donde la vestidura del Anciano de Días se describe blanca ''como la nieve.'' Es vocabulario estándar del arameo bíblico para la precipitación helada, empleado aquí simbólicamente para transmitir pureza divina, resplandor y gloria trascendente. La blancura de la nieve funciona como la comparación suprema de pureza radiante en la imaginería bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8518', 'spa', 'Colgar, suspender; usado para la ejecución por ahorcamiento, la exhibición pública de cadáveres y la suspensión de objetos', 'Colgar, suspender; usado para la ejecución por ahorcamiento, la exhibición pública de cadáveres y la suspensión de objetos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8519', 'spa', 'Murmuración, queja; protesta colectiva contra la autoridad, especialmente las quejas de Israel contra Dios en el desierto.', 'Sustantivo femenino que aparece exclusivamente en la fuente sacerdotal (P), siempre en referencia a las murmuraciones de Israel contra el SEÑOR durante la peregrinación por el desierto. El término conlleva un peso colectivo, casi corporativo: no se trata de agravios privados sino de levantamientos comunales de descontento. En Éxodo 16 la palabra se concentra densamente cuando Israel se queja por la comida, y en Números 14 y 17 resurge durante las narrativas de rebelión. El sustantivo deriva de la raíz verbal לון/לין (murmurar), y sus formas plurales en estado constructo sugieren oleadas repetidas de queja más que un solo estallido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8520', 'spa', 'Télaj (con conjunción), nombre propio: un ancestro en la genealogía de Efraín (1 Crónicas 7:25)', 'Nombre propio que aparece en los registros genealógicos de Efraín en 1 Crónicas 7:25. Su etimología es incierta y no aparece en ningún otro lugar del texto bíblico. Como muchos nombres en las genealogías de Crónicas, su función es preservar los registros de linaje tribal, conectando a los efraimitas posteriores al exilio con su herencia ancestral. Las variantes de transliteración en la Septuaginta reflejan la incertidumbre antigua sobre su pronunciación. Se trata de una figura cuya importancia radica enteramente en mantener la continuidad genealógica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8522', 'spa', 'aljaba (con sufijo ''tu''; recipiente para flechas, colgado del hombro o cinturón)', 'Este sustantivo designa la aljaba, el recipiente que contiene las flechas, apareciendo en Génesis 27:3 cuando Isaac instruye a Esaú a tomar sus armas para la cacería. La aljaba se cuelga del hombro o del cinturón, manteniendo las flechas accesibles para disparar con rapidez. Los hallazgos arqueológicos en todo el antiguo Cercano Oriente muestran la aljaba como equipo estándar de caza y guerra. El emparejamiento de aljaba y arco representa el conjunto completo de arquería, esencial tanto para la guerra como para la caza en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8523', 'spa', 'tercero (número ordinal arameo, lectura Qere que sugiere corrección de pronunciación)', 'Número ordinal arameo que significa «tercero», presente en Daniel 2:39 para describir el tercer reino en la visión de la estatua de Nabucodonosor. Es vocabulario estándar del arameo bíblico para indicar el tercero en una secuencia. La tradición masorética incluye una nota Qere que ofrece orientación sobre la pronunciación, reflejo de la atención escribal a la lectura correcta. Este ordinal es fundamental en el esquema de Daniel sobre los reinos sucesivos, cada uno representando distintos imperios en la interpretación profética de la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8523a', 'spa', 'tercero (gobernante), triunviro (adjetivo arameo que designa al tercer en mando o miembro de una tríada gobernante)', 'Término arameo que designa a un gobernante «tercero» o triunviro, presente en Daniel 5:7 como parte del honor ofrecido a quien interprete la escritura en la pared. Se trata de un derivado del ordinal «tercero» que sugiere un cargo de tercer gobernante en jerarquía o la pertenencia a una tríada de poder. El término posiblemente refleja la estructura administrativa persa, donde la autoridad se compartía entre un reducido grupo de altos funcionarios. Representa un honor significativo: ser elevado al tercer puesto más alto del imperio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8523b', 'spa', 'tercero (ordinal arameo, lectura Ketiv en Daniel 2:39, variante textual de H8523)', 'Forma Ketiv (escrita) del ordinal arameo «tercero» en Daniel 2:39, en contraste con la forma Qere (pronunciada). Esta variante textual refleja diferentes tradiciones de vocalización para el mismo texto consonántico, fenómeno habitual en la tradición masorética. Ambas formas apuntan al mismo número ordinal que identifica al tercer reino en la visión de la estatua. Tales variantes Ketiv-Qere suelen preservar tradiciones de pronunciación en competencia provenientes de distintas escuelas escribales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8524', 'spa', 'elevado, excelso, alto (adjetivo que describe altura o eminencia)', 'Adjetivo que denota elevación o altura, presente en Ezequiel 17:22 para describir el monte donde Dios plantará un vástago de cedro. El pasaje acumula términos de elevación: «monte alto y excelso», subrayando la prominencia del lugar. Se trata del monte Sion, presentado en la visión profética como el sitio más alto y eminente donde Dios establece su reino. El término transmite tanto elevación física como exaltación metafórica: el monte es a la vez alto en estatura y supremo en importancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8525', 'spa', 'Surco; zanja abierta por el arado en un campo para la siembra o el riego', 'El telem es el surco individual que el arado traza en la tierra de un campo cultivado. En la Palestina antigua, el arado producía surcos poco profundos de ocho a diez centímetros. Oseas emplea ''surcos del campo'' como metonimia de la tierra agrícola misma (10:4; 12:11), mientras que Job 31:38 personifica los surcos de la tierra clamando contra la injusticia. El Salmo 65:10 celebra a Dios regando la tierra y asentando sus surcos con lluvia, una imagen vívida de la provisión divina a través de la agricultura cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8526', 'spa', 'Talmai; nombre propio de un gigante anaquita en Hebrón y del rey de Gesur, suegro de David.', 'Talmai designa a dos personajes bíblicos distintos. El primero es uno de los tres gigantes anaquitas que habitaban en Hebrón y que fueron expulsados por las fuerzas de Caleb durante la conquista de la tierra (Num 13:22; Jos 15:14; Jue 1:10). El segundo es el rey de Gesur cuya hija Maaca se convirtió en esposa de David y madre de Absalón (2 Sam 3:3; 13:37; 1 Cr 3:2). Cuando Absalón huyó tras asesinar a Amnón, se refugió con su abuelo Talmai en Gesur. La Septuaginta ofrece variantes como Thommei, Thalmein y Tholomei, lo que refleja incertidumbre sobre la vocalización original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8527', 'spa', 'estudiante, discípulo, aprendiz (sustantivo hebreo tardío que designa al que aprende, especialmente en la instrucción musical levítica)', 'Término del hebreo tardío para estudiante o discípulo, presente en 1 Crónicas 25:8 en el contexto de la formación musical levítica. El versículo describe el sorteo para las asignaciones de servicio «maestro con alumno», evidenciando relaciones pedagógicas formales entre los músicos del templo. La palabra es rara en el hebreo bíblico, pero se vuelve común en la literatura rabínica posterior, donde se convierte en el término estándar para «discípulo». Aquí indica relaciones de enseñanza estructuradas, con músicos experimentados instruyendo a aprendices en el arte de la salmodia del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8529', 'spa', 'vestido de escarlata, ataviado de carmesí (participio Pual, describe prendas teñidas con tinte escarlata)', 'Participio Pual que significa «vestido de escarlata», aparece en Nahúm 2:3 describiendo a los guerreros de Nínive. Es un verbo denominativo derivado del sustantivo para el tinte carmesí, producido a partir del gusano תּוֹלָע. El participio indica el estado de estar ataviado con ropas teñidas de escarlata, probablemente vestimentas militares o escudos cubiertos de cuero rojo. El término paralelo «enrojecido» refuerza la imagen de guerreros engalanados en carmesí, evocando tanto el esplendor militar como el presagio de derramamiento de sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8530', 'spa', 'para la armería, para almacén de armas (sustantivo incierto, posiblemente «hileras» o «armería»; dificultades textuales)', 'Palabra difícil que aparece en Cantar de los Cantares 4:4, donde se compara el cuello de la amada con la torre de David «edificada para la armería». Su significado es incierto: las posibilidades incluyen «almacén de armas», «hileras de escudos» o «trofeos». El contexto menciona mil escudos colgados en la torre, lo que sugiere imaginería militar. Se han propuesto diversas conjeturas, incluyendo leer «escudos» en su lugar. La metáfora elogia el cuello grácil y fuerte de la amada comparándolo con una torre, pero el matiz exacto de este término sigue siendo esquivo, relacionado probablemente con la función militar o el ornamento de la torre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8532', 'spa', 'Tres (arameo) — numeral cardinal «tres», usado exclusivamente en las porciones arameas de Daniel y Esdras', 'El numeral arameo תְּלָת / תְּלָתָא (telat/telata) es el número cardinal «tres», que aparece once veces en las secciones arameas de Daniel y Esdras. Funciona de manera idéntica al hebreo שָׁלֹשׁ, pero pertenece al registro del arameo imperial de estos libros. Sus ocurrencias incluyen las tres hileras de piedra en el decreto de Ciro para el templo (Esd 6:4), los tres compañeros arrojados al horno de fuego (Dn 3:23-24), el ayuno de tres semanas de Daniel (Dn 10:2-3) y las tres costillas en la boca del oso (Dn 7:5). En español se traduce simplemente como «tres».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8534', 'spa', 'ondulados, rizos colgantes (sustantivo plural que describe la apariencia del cabello, posiblemente como frondas de palmera)', 'Palabra poco frecuente que aparece en Cantar de los Cantares 5:11 describiendo el cabello del amado. Su significado exacto es debatido: «ondulado», «colgando en racimos», «como ramas de palmera» o «como vainas de dátiles». El contexto resalta la belleza y el color oscuro de sus rizos, «negros como el cuervo». En hebreo tardío, el término se usa para montículos o lugares altos, pero aquí la imagen se refiere claramente a la textura o apariencia del cabello. La poesía árabe frecuentemente compara el cabello con elementos de la palmera, lo que podría respaldar las interpretaciones botánicas. El término transmite cabello exuberante y fluido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8535', 'spa', 'Íntegro, cabal, moralmente intachable; de personas que poseen integridad ante Dios, o de carácter apacible y sencillo. Un adjetivo rico que abarca la ', 'Íntegro, cabal, moralmente intachable; de personas que poseen integridad ante Dios, o de carácter apacible y sencillo. Un adjetivo rico que abarca la plenitud física, la integridad moral y el temperamento apacible. En Job 1:1 y 1:8, es la palabra principal que Dios usa para describir a Job: ''tam veyashar'', íntegro y recto. En Cantar de los Cantares 5:2 y 6:9, se convierte en un término de cariño íntimo, ''mi perfecta'', donde la completitud adquiere una belleza estética y relacional. Su único uso para Jacob en Génesis 25:27 revela un matiz más sosegado: un hombre de tiendas y no de campos, apacible y no inquieto, la imagen opuesta de Esaú el cazador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8536', 'spa', 'allí (adverbio arameo de lugar)', 'Equivalente arameo del hebreo שָׁם, que aparece exclusivamente en el relato de Esdras sobre la correspondencia administrativa persa relativa al templo de Jerusalén. Funciona como un simple adverbio locativo que señala los lugares de archivo en Babilonia y Ecbatana donde se guardaban los decretos reales (Esd 5:17; 6:1, 12). La construcción מִן־תַּמָּה significa «de allí» (6:6). Su uso refleja el arameo imperial como lengua franca burocrática del Imperio persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8537', 'spa', 'Integridad, plenitud, inocencia; rectitud moral del corazón, conducta intachable, simplicidad involuntaria, o plenitud y completitud temporal', 'Integridad, plenitud, inocencia; rectitud moral del corazón, conducta intachable, simplicidad involuntaria, o plenitud y completitud temporal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8538', 'spa', 'Integridad, entereza moral; rectitud de carácter mantenida ante Dios', 'Sustantivo hebreo tardío que designa la integridad moral como cualidad estable del carácter, no como un acto aislado. Es prácticamente un término teológico en el libro de Job, donde se convierte en el eje central del prólogo: Dios mismo atestigua que Job ''se aferra a su integridad'' (2:3), y la estrategia de Satanás es lograr que la abandone. La esposa de Job le insta a ''maldecir a Dios y morir'', preguntándole si todavía se aferra a su integridad (2:9). Job insiste en que jamás renunciará a ella (27:5) e invita a Dios a pesarlo en balanzas justas para confirmarla (31:6). Proverbios 11:3 extiende el concepto más allá de Job: ''la integridad de los rectos los guía''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8539', 'spa', 'Quedar atónito, pasmado; mirar con asombro o estupefacción ante algo abrumador.', 'Describe la experiencia de quedarse sin habla por el asombro, ya sea por un juicio divino, sucesos aterradores o pura admiración. En Génesis 43:33, los hermanos de José se miran unos a otros con estupor al verse sentados en orden de nacimiento por un desconocido. Isaías 29:9 emplea el imperativo con amarga ironía: ''¡Asombraos! ¡Cegaos!'' — desafiando a oyentes complacientes. La forma duplicada de Habacuc 1:5 (Qal + Hitpael) intensifica la conmoción: ''¡Asombraos enormemente!'' Esa cualidad visceral de quedarse boquiabierto define este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8540', 'spa', 'maravillas, milagros (arameo, señales y prodigios divinos)', 'Este sustantivo arameo masculino plural significa ''maravillas'' o ''milagros''—actos extraordinarios que revelan poder divino. Aparece exclusivamente en las secciones arameas de Daniel dentro de las proclamaciones de Nabucodonosor y Darío sobre Dios. Daniel 4:2-3 repite la frase ''señales y maravillas'' cuando Nabucodonosor declara ''¡cuán grandes son Sus señales, cuán poderosas Sus maravillas!'' Daniel 6:27 en el decreto de Darío igualmente alaba al Dios que ''hace señales y maravillas en el cielo y en la tierra.'' El término es el cognado arameo del hebreo mophet, enfatizando actos sobrenaturales que revelan la soberanía de Dios y evocan asombro. Los contextos uniformemente involucran reyes paganos reconociendo al Dios de Israel tras experimentar Su poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8542', 'spa', 'Tamuz (con artículo), nombre divino: deidad mesopotámica asociada con la muerte y la fertilidad (Ezequiel 8:14)', 'Nombre de una deidad mesopotámica que aparece en Ezequiel 8:14, donde se ve a mujeres llorando por Tamuz en la puerta del templo. Es Dumuzi en sumerio, un dios asociado con la vegetación, la muerte y la fertilidad cuyo culto incluía luto ritual por su muerte. Los griegos lo identificaron con Adonis. Su adoración se extendió por todo el antiguo Cercano Oriente, y el profeta condena su presencia en el templo de Jerusalén como sincretismo abominable. Posteriormente, esta deidad dio su nombre a un mes del calendario babilónico (aproximadamente junio-julio), que aún se usa en el calendario hebreo actual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8543', 'spa', 'Ayer; antiguamente, antes — frecuentemente en la expresión idiomática ''ayer y anteayer'' que significa ''en tiempos pasados''', 'Ayer; antiguamente, antes — frecuentemente en la expresión idiomática ''ayer y anteayer'' que significa ''en tiempos pasados''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8544', 'spa', 'Forma, figura visible, apariencia exterior; semejanza, imagen — usado en teofanías divinas, prohibiciones de ídolos y apariciones visionarias.', 'Sustantivo femenino que designa la forma visible o apariencia exterior de algo, prominente en dos contextos teológicos cargados de significado. En las tradiciones teofánicas describe la ''forma del SEÑOR'' que solo Moisés contempló (Nm 12:8) y la figura que Israel oyó pero no vio en Horeb (Dt 4:12, 15). En las prohibiciones contra la idolatría se empareja con פֶּסֶל (''imagen tallada'') para vedar toda representación a semejanza de las criaturas (Éx 20:4; Dt 4:16, 23, 25). La esperanza del salmista de contemplar la semejanza de Dios al despertar (Sal 17:15) y la aparición fantasmal de Job (Job 4:16) completan su rango semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8545', 'spa', 'Intercambio, sustituto; recompensa, retribución — lo que se da o devuelve en lugar de otra cosa.', 'Sustantivo derivado de la raíz de ''intercambiar'', que abarca tanto el acto concreto de sustitución como la idea abstracta de recompensa. En la legislación cúltica, se refiere al animal sustituto ofrecido cuando alguien intenta cambiar una ofrenda consagrada (Lev 27:10, 33): tanto el original como su reemplazo quedan santificados. Rut 4:7 lo emplea para la costumbre de intercambiar sandalias al confirmar una transacción. Job lo usa para la riqueza obtenida mediante el comercio (Job 20:18) y para el oro que no puede igualar el valor de la sabiduría (Job 28:17). En Job 15:31 adquiere peso moral: la ''recompensa'' del engañado será vacuidad, marcando el paso de un intercambio neutro a una consecuencia merecida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8548', 'spa', 'Continuidad; como adverbio ''continuamente, siempre, perpetuamente''; como sustantivo ''la ofrenda diaria/continua (tamid).''', 'תָּמִיד transmite la idea de algo que prosigue sin interrupción. En su uso adverbial más frecuente (unas 80 veces), modifica acciones con el sentido de ''continuamente'' o ''siempre,'' apareciendo especialmente en los Salmos para describir la alabanza incesante, la confianza permanente o la presencia divina constante (Sal 16:8; 34:2; 71:6). En su uso sustantival con artículo (הַתָּמִיד), se convierte en un término cultual preciso para el holocausto diario prescrito en Nm 28:3-6, que se proyecta en la imaginería apocalíptica de Daniel, donde la supresión del תָּמִיד señala la profanación definitiva (Dn 8:11; 12:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8549', 'spa', 'Completo, íntegro, sin defecto — referido a animales sacrificiales, personas moralmente rectas, el camino perfecto de Dios y períodos de tiempo comple', 'Completo, íntegro, sin defecto — referido a animales sacrificiales, personas moralmente rectas, el camino perfecto de Dios y períodos de tiempo completos. Un adjetivo de integridad y plenitud que abarca desde la inspección de corderos para el sacrificio hasta el carácter de Dios mismo. Su uso más frecuente (aproximadamente 50 veces) es el requisito cultual de que las ofrendas sean ''sin defecto,'' físicamente completas, sin tacha alguna (Lv 1:3, Éx 12:5). Pero la palabra trasciende con creces el altar: Noé fue ''perfecto en su generación'' (Gn 6:9), a Abraham se le ordena ''anda delante de mí y sé perfecto'' (Gn 17:1), y la ley del Señor es declarada ''perfecta'' (Sal 19:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8550', 'spa', 'Tumim: uno de los dos objetos sagrados (junto con el Urim) usados por el sumo sacerdote para consultar la voluntad divina', 'Los Tumim, emparejados con el Urim, eran objetos sagrados colocados en el pectoral del sumo sacerdote para obtener decisiones divinas. Su naturaleza exacta sigue siendo incierta; el nombre probablemente deriva de la raíz que significa ''plenitud'' o ''perfección''. Éxodo 28:30 y Levítico 8:8 prescriben su colocación dentro del pectoral del juicio. Deuteronomio 33:8 los asigna a la tribu de Leví. Tras el exilio, Esdras 2:63 y Nehemías 7:65 registran que ciertos sacerdotes fueron excluidos del servicio hasta que un sacerdote pudiera consultar ''con Urim y Tumim'', lo que sugiere que la práctica oracular había caído en desuso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8551', 'spa', 'Asir, sostener o aferrarse; desde sujetar físicamente, hasta sustentar a alguien con fuerza, o aferrarse a la sabiduría y la justicia.', 'Asir, sostener o aferrarse; desde sujetar físicamente, hasta sustentar a alguien con fuerza, o aferrarse a la sabiduría y la justicia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8552', 'spa', 'Completarse o terminarse; consumirse o perecer; (Hifil) llevar a término o destruir; (Hitpael) mostrarse íntegro. Un verbo cuyo significado básico es ', 'Completarse o terminarse; consumirse o perecer; (Hifil) llevar a término o destruir; (Hitpael) mostrarse íntegro. Un verbo cuyo significado básico es ''estar completo'' o ''llegar a su fin,'' compartido con el árabe tamma y el siríaco tam. En su forma Qal describe cosas que alcanzan su conclusión natural: provisiones que se agotan (Gn 47:15, 18), períodos de tiempo que expiran o tareas que se terminan. Sin embargo, la misma raíz se oscurece hacia ''consumirse, perecer'' cuando se aplica a personas bajo juicio (Nm 14:35; Dt 2:16). El Hifil causativo refleja ambos polos: completar una obra (2 R 22:4) o consumir a los enemigos (Ez 22:15). Lo más notable es el Hitpael reflexivo, donde la plenitud se convierte en perfección moral: ''te muestras íntegro'' (2 S 22:26; Sal 18:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8553', 'spa', 'Timna — ciudad cananea en la Sefela, vinculada al encuentro de Judá con Tamar y a la esposa filistea de Sansón', 'Timna (תִּמְנָה) es una ciudad en las tierras bajas de la Sefela, en la frontera entre Judá y Filistea. Aparece por primera vez cuando Judá sube a Timna para la esquila de ovejas y se encuentra con Tamar junto al camino (Gn 38:12-14). Josué la incluye entre las ciudades de Judá (Jos 15:10, 57) y también como ciudad danita (Jos 19:43). Su papel más destacado se da en el ciclo de Sansón: este baja a Timna, ve a una mujer filistea e insiste en casarse con ella (Jue 14:1-5). Los filisteos la capturan durante el reinado de Acaz (2 Cr 28:18). El sitio se identifica con Tel Batash en el valle del Sorec.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8554', 'spa', 'el timnateo, gentilicio con artículo: habitante de Timna, aplicado a la esposa de Sansón (Jueces 15:6)', 'Adjetivo gentilicio con artículo que significa «el timnateo» o «la mujer de Timna». Aparece en Jueces 15:6 refiriéndose a la malograda esposa de Sansón, cuya identificación por ciudad en lugar de nombre personal subraya su papel en el conflicto tribal. Timna era una ciudad fronteriza entre Israel y Filistea, lo que hacía los matrimonios allí políticamente delicados. La designación la identifica como forastera, una mujer filistea cuyo matrimonio con Sansón desencadena el conflicto que conduce a su trágica muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8555', 'spa', 'Timna; nombre edomita de una concubina de Elifaz, hermana horita de Lotán y un jefe edomita.', 'Timna es un nombre edomita empleado tanto para figuras masculinas como femeninas en las genealogías de Génesis 36 y 1 Crónicas 1. Como mujer, Timna era hermana de Lotán el horita (Gn 36:22; 1 Cr 1:39) y concubina de Elifaz hijo de Esaú, de quien nació Amalec (Gn 36:12). Como nombre masculino, Timna aparece entre los jefes (alluphim) de Edom (Gn 36:40; 1 Cr 1:51). En 1 Crónicas 1:36 se le enumera entre los hijos de Elifaz, lo que parece fusionar la tradición de la concubina con una lectura de nombre tribal. La Septuaginta lo traduce consistentemente como Thamna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8556a', 'spa', 'En Timnat-heres, topónimo con preposición: lugar de sepultura de Josué en la serranía de Efraín', 'Topónimo compuesto que aparece en Jueces 2:9 y significa ''territorio del sol'' o ''porción de Heres''. Es el lugar donde Josué fue sepultado, en la serranía de Efraín. El nombre tiene una variante, Timnat-sera, en Josué 19:50 y 24:33, con los elementos invertidos. Se identifica con la actual Tibneh, a unos 27 kilómetros al noroeste de Jerusalén. Algunos estudiosos sugieren que el nombre podría reflejar un antiguo lugar de culto solar, aunque en tiempos de Josué era simplemente su heredad y lugar de sepultura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8557', 'spa', 'Derretimiento, disolución (sustantivo que describe el proceso de fundirse, usado para el rastro baboso del caracol)', 'Sustantivo que denota derretimiento o disolución, presente en el Salmo 58:8 con una imagen vívida: ''como el caracol que se deshace en baba''. La metáfora alude al rastro viscoso que deja el caracol al avanzar, como si la criatura se fuera disolviendo. El salmista emplea esta imagen impactante para referirse a los malvados, quienes deberían deshacerse y desaparecer. La palabra capta el proceso de lo sólido volviéndose líquido: disolución y desvanecimiento total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8558', 'spa', 'Palmera datilera — árbol alto y esbelto que da fruto y sombra, símbolo de belleza, victoria y vida floreciente', 'El sustantivo תָּמָר (tamar) designa la palmera datilera (Phoenix dactylifera), uno de los árboles más emblemáticos del antiguo Oriente Próximo, apreciado por su fruto, su sombra y su porte majestuoso. Israel encuentra palmeras en el oasis de Elim con sus setenta palmeras (Éx 15:27). Se agitan ramas de palmera en la Fiesta de los Tabernáculos (Lv 23:40; Neh 8:15). Jericó es «la ciudad de las palmeras» (Dt 34:3; Jue 1:16; 3:13). El salmista declara que «el justo florecerá como la palmera» (Sal 92:12). El templo de Salomón y el templo visionario de Ezequiel presentan palmeras talladas como motivos decorativos (1 R 6:29, 32; Ez 40:16, 22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8559', 'spa', 'Tamar — nombre propio que significa ''palmera datilera'', llevado por tres mujeres y usado para un lugar en la frontera de Judá', 'Tamar — nombre propio que significa ''palmera datilera'', llevado por tres mujeres y usado para un lugar en la frontera de Judá');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8561', 'spa', 'Ornamento de palmera tallada usado como decoración arquitectónica en el templo de Salomón y en el templo visionario de Ezequiel.', 'Ornamento de palmera tallada usado como decoración arquitectónica en el templo de Salomón y en el templo visionario de Ezequiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8562', 'spa', 'cosméticos, ungüentos de purificación, tratamientos de embellecimiento', 'Término que aparece casi exclusivamente en la narración del régimen de belleza de Ester, describiendo las preparaciones cosméticas y los ungüentos utilizados durante el proceso de purificación de doce meses para las jóvenes que ingresaban al harén del rey (Est 2:3, 9, 12). Los tratamientos incluían aceite de mirra y perfumes. Su única aparición fuera de Ester es textualmente incierta (Pr 20:30, lectura Qeré). La raíz sugiere limpieza o pulido, de ahí tratamientos que purifican y embellecen simultáneamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8563', 'spa', 'amargura, duelo amargo (plural intensivo, dolor profundo)', 'Este sustantivo masculino plural (plural intensivo) denota amargura, específicamente duelo amargo o profundo. Jeremías 6:26 llama a ''hacer duelo de amargura''—luto amargo por un hijo único, la pérdida más dolorosa. Jeremías 31:15 describe a Raquel llorando con ''llanto amargo'' por sus hijos exiliados. Oseas 12:14 advierte que Efraín ha provocado a Dios ''amargamente'' (adverbialmente)—con acciones que causan grave ofensa. La forma intensifica el concepto raíz de amargura (marar), enfatizando dolor extremo o provocación. Los contextos uniformemente involucran tristeza profunda o afrenta seria que evoca emoción amarga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8564', 'spa', 'Señales del camino, mojones, indicadores (sustantivo plural para marcadores que indican la ruta, usado metafóricamente)', 'Sustantivo en plural que designa señales del camino o mojones, presente en Jeremías 31:21 dentro de un oráculo de restauración. Dios ordena a Israel ''pon señales en el camino'' y ''coloca indicadores'' para que pueda hallar la ruta de regreso del exilio. El término probablemente proviene de una raíz árabe que significa señales o marcadores: montones de piedras o postes que indican senderos por territorio desconocido. Metafóricamente, Israel debe recordar el camino por el que fue al exilio para poder regresar, marcando así su viaje tanto espiritual como físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8565', 'spa', 'Como el monstruo, como la serpiente (preposición + sustantivo, describe a Faraón como monstruo marino o dragón)', 'Esta frase aparece en Ezequiel 32:2, donde se compara a Faraón con un monstruo marino. La palabra hebrea תַּנִּין puede significar serpiente, dragón o monstruo marino, una criatura mitológica que representa el caos. El texto presenta dificultades textuales, con algunos manuscritos que confunden la forma plural. La imagen presenta a Faraón como un gran monstruo del caos en el Nilo, al que Dios capturará y destruirá. Esto se apoya en la mitología del antiguo Cercano Oriente, donde los dioses creadores derrotan a monstruos marinos que representan el caos primordial. El rey de Egipto, pese a su poder, no es más que una bestia que Dios vencerá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8568', 'spa', 'chacal, cánido salvaje de lugares desolados, conocido por su aullido lúgubre', 'Esta palabra hebrea denota el chacal, un cánido salvaje que habita regiones desiertas y desoladas. El animal aparece en la Escritura como símbolo de devastación y abandono, su aullido inquietante resonando por lugares yermos. En Lamentaciones 4:3, los chacales son notados por amamantar a sus crías—contrastando con la crueldad del pueblo de Jerusalén durante el asedio. Los textos proféticos usan chacales para marcar lugares de juicio divino que se han vuelto ruinas inhabitables, sus gritos lastimeros un recordatorio de antigua gloria convertida en cenizas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8570', 'spa', 'Fruto, producto; el rendimiento de la tierra cultivada, de los árboles o, metafóricamente, el florecimiento de un pueblo', 'Tenuva designa el rendimiento tangible del trabajo agrícola: el producto del campo y del huerto. Deuteronomio 32:13 celebra a Dios alimentando a Israel con ''el producto del campo'', y Ezequiel 36:30 promete la abundancia restaurada del ''fruto del árbol y producto del campo''. En Jueces 9:11, la higuera rehúsa abandonar ''mi buen fruto'' para gobernar sobre los demás árboles. Lamentaciones 4:9 invierte la imagen: la gente desfallece ''por falta del fruto del campo''. Isaías 27:6 extiende la metáfora a Israel mismo, cuyo florecimiento futuro ''llenará la faz del mundo de fruto''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8571', 'spa', 'Lóbulo de la oreja: término técnico sacerdotal usado exclusivamente en rituales de consagración y purificación con sangre o aceite.', 'Término anatómico especializado que designa el lóbulo carnoso en la parte inferior de la oreja externa. Aparece exclusivamente en contextos rituales dentro de la fuente sacerdotal, siempre en la construcción tenukh ozen («lóbulo de la oreja de...»). Durante la consagración de Aarón y sus hijos, Moisés aplicó sangre del sacrificio sobre el lóbulo de la oreja derecha, el pulgar derecho y el dedo gordo del pie derecho (Éx 29:20; Lv 8:23-24). La misma tríada de partes corporales recibe sangre y aceite en el ritual de purificación del leproso sanado (Lv 14:14, 17, 25, 28). La Septuaginta traduce lobos tou otos y la Vulgata extremum auriculae, confirmando la interpretación antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8572', 'spa', 'Somnolencia, adormecimiento; sueño ligero asociado con visiones divinas o con la pereza', 'Tenuma describe un estado de sueño ligero o somnolencia, distinto del sueño profundo (תַּרְדֵּמָה) aunque a veces aparece emparejado con este. En Job 33:15, los adormecimientos sobre el lecho se convierten en la ocasión para que Dios hable mediante visiones y sueños. En Proverbios, la palabra adquiere un giro marcadamente negativo: ''un poco de sueño, un poco de adormecimiento'' conduce a que la pobreza llegue como un ladrón (6:10; 24:33). El Salmo 132:4 recoge el voto de David de no conceder adormecimiento a sus párpados hasta encontrar morada para el arca, imagen de devoción urgente e insomne.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8573', 'spa', 'Ofrenda mecida presentada ritualmente ante el SEÑOR; también el acto físico de blandir o agitar', 'Ofrenda mecida presentada ritualmente ante el SEÑOR; también el acto físico de blandir o agitar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8574', 'spa', 'Horno, hornaza; estufa portátil de barro para hornear pan, empleada también en sentido figurado para la ira divina y el calor abrasador. El sustantivo', 'Horno, hornaza; estufa portátil de barro para hornear pan, empleada también en sentido figurado para la ira divina y el calor abrasador. El sustantivo תַּנּוּר (tannur) designa un gran recipiente de barro o estufa portátil utilizada en todo el antiguo Oriente Próximo para cocer pan. La palabra es un préstamo cultural que viajó del persa ''tanura'' a través del arameo hacia el hebreo y el árabe, reflejando la cultura material compartida de la panificación entre las civilizaciones semíticas. En sentido literal, aparece en leyes sobre pureza ritual (Lv 11:35), ofrendas de grano cocidas en horno (Lv 2:4) y el dramático horno humeante del pacto de Dios con Abraham (Gn 15:17). En sentido figurado, los profetas aprovecharon su calor intenso como metáfora del juicio divino: ''viene el día, ardiente como un horno'' (Mal 4:1), y Oseas compara las pasiones latentes de los conspiradores con un horno calentado por el panadero (Os 7:4, 7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8575', 'spa', 'Consolación, consuelo; palabras o actos que alivian el duelo y restauran la esperanza', 'Tanchumim aparece solo en plural, transmitiendo la plenitud o intensidad del consuelo ofrecido a quienes atraviesan el duelo. Jeremías 16:7 describe la copa de consolación compartida en una casa de luto, un acto ritual concreto. En Job, Elifaz pregunta si ''las consolaciones de Dios'' son demasiado pequeñas para Job (15:11), y este replica que los discursos de sus amigos son ''consolaciones'' vacías (21:2). El Salmo 94:19 testimonia que las consolaciones de Dios deleitan el alma en medio de pensamientos angustiosos. Isaías 66:11 promete que la Jerusalén restaurada amamantará a sus hijos del ''pecho de sus consolaciones''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8577a', 'spa', 'Chacal — cánido salvaje aullador que habita ruinas y yermos, emblema de desolación absoluta y juicio divino', 'El sustantivo תַּן (tan) se refiere al chacal, un cánido salvaje que merodea por lugares desiertos y llena la noche con aullidos estremecedores. En la imaginería bíblica, el chacal es el habitante por excelencia de las ruinas: su presencia indica que un lugar ha sido entregado a la desolación. Job se lamenta de haberse vuelto «hermano de chacales» (Job 30:29), y Miqueas aúlla como ellos en señal de duelo (Mi 1:8). Los profetas recurren al chacal como marca de juicio: Babilonia se convierte en «morada de chacales» (Is 13:22; Jer 51:37), los palacios de Edom en «guarida de chacales» (Is 34:13), y Jerusalén en cubil de chacales (Jer 9:11; 10:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8577b', 'spa', 'Gran serpiente, dragón o monstruo marino; usado tanto para serpientes reales como para criaturas del caos cósmico y seres marinos. Una de las palabras', 'Gran serpiente, dragón o monstruo marino; usado tanto para serpientes reales como para criaturas del caos cósmico y seres marinos. Una de las palabras más evocadoras del mundo bíblico para designar criaturas, תַּנִּין (tannin) abarca lo natural y lo mitológico. En Éxodo 7, la vara de Aarón se convierte en una ''serpiente'' ante Faraón — una serpiente grande y temible que devora a las demás. En la poesía profética, el término alcanza proporciones cósmicas: el dragón del caos que Dios destruye (Is 27:1; 51:9), el monstruo con el que se compara a Faraón acechando en el Nilo (Ez 29:3; 32:2), y el devorador de Jeremías 51:34. Sin embargo, Génesis 1:21 usa la misma palabra para las grandes criaturas marinas que Dios crea a propósito — no enemigos sino maravillas. Los Salmos mantienen ambos polos: las cabezas aplastadas de tannin en el Salmo 74:13 y los monstruos marinos convocados a la alabanza en el Salmo 148:7.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8578', 'spa', 'Segunda (número ordinal arameo, forma femenina que indica la segunda en una secuencia)', 'Número ordinal arameo que significa ''segunda'', presente en Daniel 7:5 al describir la segunda bestia en la visión de Daniel. Es vocabulario estándar del arameo bíblico; la forma femenina concuerda gramaticalmente con ''bestia'' (חֵיוָה). El término identifica la segunda en la secuencia de cuatro bestias que representan imperios sucesivos. Es vocabulario ordinal directo, pero esencial para seguir la historia esquemática de los reinos en la visión apocalíptica de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8579', 'spa', 'por segunda vez, de nuevo (adverbio arameo que indica repetición de una acción)', 'Adverbio arameo que significa «por segunda vez» o «de nuevo», presente en Daniel 2:7 cuando los caldeos reiteran al rey su petición de que les cuente el sueño antes de interpretarlo. Es vocabulario temporal estándar que señala repetición. El adverbio subraya la insistencia de los caldeos y la creciente frustración de Nabucodonosor ante sus demandas. Marca con claridad que la acción se realiza otra vez, situando al lector en el tenso diálogo entre el monarca y sus consejeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8580', 'spa', 'ave o reptil inmundo, posiblemente lechuza común, lechuza blanca, ibis, camaleón o lagarto', 'Este término aparece en las leyes levíticas de pureza pero presenta un genuino enigma de identificación. En Levítico 11:18 y Deuteronomio 14:16, designa un ave inmunda—posiblemente la lechuza común, lechuza blanca o ibis. Sin embargo, en Levítico 11:30, la misma palabra lista entre reptiles inmundos, sugiriendo un camaleón o lagarto. Lexicógrafos antiguos propusieron que el camaleón fue nombrado por supuestamente vivir del aire, aunque esta etimología no encaja con el uso aviar. La evidencia multilingüe revela incertidumbre continua del traductor, con cada tradición haciendo elecciones diferentes sobre esta enigmática criatura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8581', 'spa', 'Abominar, detestar, actuar abominablemente o ser aborrecido; expresando profunda repulsión ritual, moral y emocional', 'Abominar, detestar, actuar abominablemente o ser aborrecido; expresando profunda repulsión ritual, moral y emocional');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8582', 'spa', 'Extraviarse, vagar, errar; en Hifil: hacer errar, desviar; referido al extravío físico, moral o por embriaguez. El verbo תָּעָה abarca todo el arco de', 'Extraviarse, vagar, errar; en Hifil: hacer errar, desviar; referido al extravío físico, moral o por embriaguez. El verbo תָּעָה abarca todo el arco de desviarse: desde un niño literalmente perdido en el desierto, hasta una nación espiritualmente descarriada de Dios, hasta un borracho tambaleándose por el vino. Agar ''vagó'' en el desierto de Beerseba (Gn 21:14) con la misma raíz que describe a Israel ''extraviándose'' de los mandamientos de Dios (Sal 119:176) y a falsos profetas ''haciendo errar'' a pueblos enteros (2 R 21:9). El Hifil causativo, que representa casi la mitad de las ocurrencias, añade un agente siniestro: alguien o algo que activamente causa el extravío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8583', 'spa', 'Toi (Tou): rey de Hamat que envió tributo a David tras la derrota de Hadadezer', 'Toi (también escrito Tou en Cronicas) fue el rey de Hamat, una ciudad-estado aramea junto al rio Orontes. Cuando David derroto a Hadadezer de Soba, Toi envio a su hijo Joram con vasos de oro, plata y bronce para felicitar a David, pues Hadadezer habia sido tambien enemigo de Toi (2 S 8:9-10). El relato paralelo de Cronicas (1 Cr 18:9-10) escribe el nombre como Tou. La variacion probablemente refleja diferencias dialectales en la transmision y no a dos individuos distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8584', 'spa', 'testimonio, atestación, mandato profético o uso establecido', 'Este sustantivo lleva el peso de testigo autoritativo e instrucción vinculante. En Isaías, aparece emparejado con ''torah'' (enseñanza), designando el testimonio del profeta que debe ser sellado y preservado entre los discípulos. La palabra transmite no meramente testigo verbal sino atestación solemne con fuerza legal. En Rut 4:7, describe la práctica consuetudinaria de intercambio de sandalia que validaba transacciones de propiedad en el antiguo Israel. El término une testimonio personal y tradición establecida, marcando tanto palabra profética como costumbre comunal como testigos vinculantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8585a', 'spa', 'Canal de agua, conducto o zanja — un paso artificial para dirigir el flujo del agua.', 'Se refiere a cualquier vía acuática construida para conducir agua, ya sea un canal de riego, un conducto urbano o una zanja excavada con un propósito específico. La palabra aparece en contextos variados pero relacionados: Ezequiel 31:4 describe ríos que envían sus canales para nutrir el gran cedro de Asiria; Job 38:25 pregunta quién abrió un canal para el aguacero; y en 1 Reyes 18:32-38, Elías cava una zanja alrededor de su altar en el Carmelo que se llena de agua antes de que el fuego del SEÑOR lo consuma. El famoso conducto de Isaías 7:3 y 2 Reyes 18:17 es el acueducto cerca de Jerusalén donde tuvieron lugar encuentros decisivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8587', 'spa', 'cosa oculta, secreto, los misterios escondidos de sabiduría y corazón', 'Este término alcanza el reino de lo que yace bajo la apariencia superficial—lo oculto, lo secreto, lo escondido. Job lo usa para hablar de traer cosas ocultas a la luz y de los secretos de la sabiduría que exceden el cálculo humano. Los Salmos lo emplean para los pensamientos ocultos del corazón que solo Dios puede sondear. La palabra lleva un aura de misterio, señalando realidades oscurecidas de la vista ordinaria. Ya sea describiendo tesoros geológicos enterrados en la tierra o verdades espirituales veladas del observador casual, este sustantivo marca la frontera entre visible e invisible, conocido y desconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8588', 'spa', 'Delicadeza, lujo, deleite exquisito; placer refinado o ternura mimada', 'El sustantivo hebreo ta''anug transmite un sentido de placer lujoso, deleite refinado y ternura delicada. En Proverbios 19:10 describe un estilo de vida suntuoso impropio de un necio, mientras que Eclesiastes 2:8 emplea el plural para los deleites acumulados por Salomon. En Cantar de los Cantares 7:6 aparece en una interpelacion intima a la amada, vinculando el placer sensorial con el amor. Miqueas 1:16 y 2:9 desplazan el registro hacia el afecto tierno: ''hijos delicados'' y ''casas preciadas'', cosas queridas que se perderan en el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8589', 'spa', 'de mi ayuno, de mi aflicción (preposición + sustantivo con sufijo, referido a la abnegación o angustia penitencial)', 'Esta expresión aparece en Esdras 9:5, en un versículo de cierta complejidad textual. La forma sugiere «de mi ayuno» o «de mi aflicción», pues Esdras se levanta de su postura penitencial. La raíz se relaciona con aflicción, ayuno o abnegación, y Esdras ha estado en duelo por el pecado de Israel. La frase marca la transición del sufrimiento silencioso a la oración vocal. Aunque la forma es inusual y los intérpretes debaten si se refiere específicamente al ayuno o a la aflicción en sentido amplio, el contexto es claramente penitencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8590', 'spa', 'Taanac: antigua ciudad cananea en el valle de Jezreel cerca de Meguido, asignada a la tribu de Manasés.', 'Taanac (actual Tell Ta''annek) era una ciudad cananea fortificada en la gran llanura, a unos siete kilómetros al sur-sureste de Meguido. Aparece en listas de conquista, asignaciones tribales y en el Cántico de Débora, donde «los reyes vinieron y pelearon en Taanac, junto a las aguas de Meguido» (Jue 5:19). Fue asignada a Manasés aunque se encontraba dentro del territorio de Isacar, lo cual refleja las complejas realidades del asentamiento incompleto de Israel en Canaán. Roboam la incluyó en su red defensiva de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8592', 'spa', 'poderío, fortaleza (forma plural intensiva que enfatiza fuerza abundante o poder abrumador)', 'Este sustantivo poco frecuente aparece únicamente en el Salmo 68:35, donde intensifica el concepto de poderío divino mediante un plural de majestad o intensidad. La construcción hebrea empareja «fuerza» (עֹז) con «poderío abundante» (תַּעֲצֻמוֹת), creando un crescendo de imágenes de poder. La evidencia multilingüe lo traduce consistentemente como poder o fortaleza, captando el sentido de una fuerza formidable y abrumadora, no de mera capacidad. Se trata de la plenitud del poder divino otorgado a su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8593', 'spa', 'Navaja o cuchillo para cortar; vaina o funda para una espada. El sustantivo תַּעַר (ta''ar) abarca dos objetos notablemente distintos unidos solo por s', 'Navaja o cuchillo para cortar; vaina o funda para una espada. El sustantivo תַּעַר (ta''ar) abarca dos objetos notablemente distintos unidos solo por su forma de hoja. En un grupo de pasajes es una navaja o cuchillo cortante — el instrumento que no debe tocar la cabeza de un nazareo (Nm 6:5), empleado como símil de una lengua afilada (Sal 52:2), e incluso usado del cortaplumas de un escriba para cortar un rollo (Jer 36:23). En el otro grupo, es la vaina o funda de una espada, el estuche del que se desenvainaba la hoja de Goliat (1 S 17:51) y al que Ezequiel ordena que regrese la espada (Ez 21:35). BDB trata acertadamente estos como dos sentidos distintos de la misma palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8596', 'spa', 'Pandero, tamboril — pequeño tambor de mano percutido en celebraciones, adoración y procesiones triunfales.', 'Pandero, tamboril — pequeño tambor de mano percutido en celebraciones, adoración y procesiones triunfales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8597', 'spa', 'Belleza, gloria, esplendor; honor y renombre; ornamento y galas. Estrechamente relacionado con el verbo פָּאַר (''embellecer, glorificar''), este sustan', 'Belleza, gloria, esplendor; honor y renombre; ornamento y galas. Estrechamente relacionado con el verbo פָּאַר (''embellecer, glorificar''), este sustantivo abarca un espectro que va desde el adorno tangible hasta la gloria trascendente. Las vestiduras sacerdotales se hacen ''para gloria y hermosura'' (Éx 28:2, 40), donde la magnificencia física de los ornamentos encarna el honor divino. En la literatura profética y sapiencial describe la corona de gloria que acompaña a la vejez justa (Pr 16:31) y el renombre que Dios destina para Israel entre las naciones (Dt 26:19). Isaías lo emplea tanto para galas concretas como los adornos de los tobillos (Is 3:18) como para las vestiduras gloriosas de Sion (Is 52:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8598', 'spa', 'Manzano o su fruto; árbol fragante usado en la poesía bíblica como imagen de amor, belleza y refrigerio.', 'Designa un árbol frutal dulce y aromático junto con su fruto, identificado tradicionalmente como el manzano, aunque algunos estudiosos han propuesto el albaricoque, el cidro o el membrillo. En el Cantar de los Cantares, el amado es comparado con este árbol entre los árboles del bosque (Cnt 2:3), y su fruto alivia a quien languidece de amor (Cnt 2:5). La evidencia multilingüe es notablemente uniforme: español ''manzano/manzanas'', francés ''pommier/pommes'' e inglés ''apple'' convergen en la identificación con la manzana. Proverbios 25:11 emplea el fruto dorado como figura de la palabra dicha a tiempo, mostrando que la imagen evocaba belleza y perfección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8599a', 'spa', 'Tapúaj (nombre propio; hijo de Hebrón en la genealogía de Judá, 1 Crónicas 2:43)', 'Nombre propio que aparece en la genealogía de los descendientes de Judá. Tapúaj fue hijo de Hebrón según 1 Crónicas 2:43. El nombre es idéntico en forma a la palabra hebrea para «manzana» o «manzano», aunque la conexión etimológica es incierta. La Septuaginta lo transcribe como Θαπους o Θαφφου, mostrando variación en la transliteración griega. Este personaje es distinto del topónimo Tapúaj que aparece en otros pasajes de la Escritura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8599b', 'spa', 'Tapua; toponimo cananeo que significa ''manzana'', designa ciudades en Juda y Efrain-Manases', 'Tapua (''manzana'' o ''ciudad de la manzana'') designa al menos dos localidades distintas en la tierra prometida. Una se encuentra en la llanura de Juda (Jos 15:34) y otra en la frontera disputada entre Efrain y Manases (Jos 12:17; 16:8; 17:8), donde tambien aparece el nombre relacionado ''En-Tapua'' (''fuente de Tapua''). La Septuaginta traduce el nombre de diversas formas — Tafut, Tafus y Tafet —, lo cual refleja la dificultad que tuvieron los traductores antiguos para estabilizar este toponimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8600', 'spa', 'dispersiones, esparcimientos (sustantivo que describe el estado o acto de ser dispersado)', 'Este término aparece en Jeremías 25:34 en un contexto textual difícil que ha motivado diversas enmiendas académicas. El sentido básico implica dispersión o esparcimiento, probablemente referido a los pastores (líderes) de Israel siendo dispersados como juicio divino. BDB señala considerable incertidumbre textual, y algunos estudiosos leen la forma como verbal en lugar de sustantiva. Las glosas multilingües apuntan consistentemente a «dispersiones» o «esparcimientos», aunque traductores al francés y al alemán han colocado el término entre corchetes, reconociendo las dificultades textuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8601', 'spa', 'piezas horneadas, fragmentos rotos (término incierto, posiblemente pedazos de una ofrenda de cereal)', 'Palabra de significado textualmente incierto que aparece únicamente en Levítico 6:21 (6:14 en las versiones en inglés), dentro de las instrucciones para la ofrenda de cereal. BDB la clasifica como «palabra dudosa»; la traducción tradicional «piezas horneadas» se basa en derivarla de la raíz que significa «hornear». Sin embargo, muchos eruditos enmiendan el texto para leer un verbo de la raíz פתת, que significa «desmenuzar», lo cual daría «la desmenuzarás en pedazos». La evidencia multilingüe refleja esta incertidumbre: algunos traductores la vierten como «tortas cocidas» o «porciones», mientras otros señalan la dificultad textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8602b', 'spa', 'Enjalbegadura, cal; revestimiento de yeso usado para cubrir muros, metáfora de falsas garantías proféticas', 'En las visiones proféticas de Ezequiel, תָּפֵל designa la enjalbegadura o cal que los falsos profetas aplican sobre un muro endeble, dándole apariencia de solidez cuando en realidad carece de ella. La imagen literal aparece en Ezequiel 13:10-15, donde Dios promete que la lluvia, el granizo y el viento dejarán al descubierto la construcción deficiente. En 22:28, el mismo término funciona como metáfora incisiva: los profetas ''enjalbegan'' sus mentiras, recubriendo la falsedad con un barniz de autoridad divina. El alemán ''Tünche'' capta este matiz con precisión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8603', 'spa', 'Tofel (topónimo; lugar en o cerca del Arabá mencionado en Deuteronomio 1:1)', 'Nombre geográfico que aparece en Deuteronomio 1:1 como uno de los lugares donde Moisés pronunció sus discursos de despedida. Tradicionalmente se identifica con la moderna Tafileh, a unos 24 kilómetros al sureste del Mar Muerto, aunque esta identificación presenta dificultades fonéticas (la ת hebrea no corresponde naturalmente a la ط árabe). La Septuaginta lo traduce como Τοφολ. El nombre se menciona junto a otros marcadores geográficos para situar los últimos discursos de Moisés a Israel en el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8604', 'spa', 'indecoro, insensatez moral, necedad que ofende la rectitud', 'Este sustantivo denota indecoro moral e intelectual: comportamiento o palabras que carecen del debido decoro, sabiduría o rectitud. En Job 1:22, describe lo que Job evitó cuidadosamente: no atribuyó ''indecoro'' a Dios ni siquiera en el sufrimiento extremo, negándose a acusar a Dios de actuar mal. Jeremías lo usa para condenar a los profetas de Samaria por su necedad ofensiva. El término sugiere algo moralmente desagradable, indecoroso a los ojos de la justicia. Es lo opuesto a la sabiduría y la propiedad, marcando palabras o conducta que violan las normas divinas de lo que es apropiado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8605', 'spa', 'Oración o súplica dirigida a Dios, ya sea petición personal, intercesión u oración litúrgica en el templo. Derivado del Hitpael de פָּלַל (''orar''), תְ', 'Oración o súplica dirigida a Dios, ya sea petición personal, intercesión u oración litúrgica en el templo. Derivado del Hitpael de פָּלַל (''orar''), תְּפִלָּה abarca toda la gama de la comunicación verbal con Dios: desde las peticiones privadas de David en los Salmos hasta la solemne oración de dedicación de Salomón en el templo (1 R 8:38, 54). La impactante declaración de Isaías de que la casa de Dios será llamada ''casa de oración'' para todas las naciones (Is 56:7) muestra cómo la palabra porta un peso comunitario y escatológico. Las traducciones multilingües apuntan uniformemente a un mismo núcleo: ''prayer'' en inglés, ''oración'' en español, ''priere'' en francés, ''Gebet'' en alemán, todas convergiendo en el acto de dirigirse a lo divino con ferviente ruego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8606', 'spa', 'horror, terror (específicamente el espanto o pavor que alguien inspira en los demás)', 'Sustantivo que denota el horror o terror que alguien o algo provoca en otros. En Jeremías 49:16, Dios se dirige a Edom respecto al «horror que tú inspiras» (literalmente «tu calidad de espanto»), refiriéndose a la intimidación que Edom creía proyectar sobre las demás naciones. El término aparece en forma exclamatoria, posiblemente en tono de burla hacia la autopercibida ferocidad de Edom. Aunque BDB señala cierta incertidumbre textual, el sentido básico de infundir miedo o pavor es claro. El español «horror» y el inglés «terribleness» captan bien ese matiz de intimidación proyectada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8609', 'spa', 'coser, unir con hilo; zurcir prendas o, en sentido figurado, adherir algo a la propia piel', 'Este verbo aparece en contextos tanto literales como figurados. Génesis 3:7 describe la primera confección humana de vestimenta: Adán y Eva cosiendo hojas de higuera tras la caída. Job lo emplea metafóricamente al decir que ha «cosido cilicio sobre su piel» (16:15), imagen poética de un duelo inseparable de su ser. Eclesiastés lo sitúa entre los ritmos de la vida: «tiempo de rasgar y tiempo de coser» (3:7). Ezequiel condena a las mujeres que «cosen bandas mágicas» en las muñecas (13:18), una práctica cúltica prohibida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8610', 'spa', 'Agarrar, capturar, asir; tomar o aprehender en Qal; empuñar un instrumento; ser apresado en Nifal. תָּפַשׂ es el verbo principal de la Biblia hebrea p', 'Agarrar, capturar, asir; tomar o aprehender en Qal; empuñar un instrumento; ser apresado en Nifal. תָּפַשׂ es el verbo principal de la Biblia hebrea para asir con fuerza, ya sea a una persona en un arresto, una ciudad en una conquista o una herramienta en un uso diestro. Su alcance va desde la mujer de Potifar agarrando la vestidura de José (Gn 39:12) hasta Jubal como el que ''maneja'' la lira y la flauta (Gn 4:21). El Nifal pasivo, con 15 apariciones, describe sistemáticamente ciudades que caen bajo asedio y personas atrapadas por enemigos, como las advertencias de Jeremías de que Jerusalén será ''tomada'' (Jer 34:3; 38:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8611', 'spa', 'escupitajo, acto de escupir (específicamente escupir en el rostro como expresión de desprecio)', 'Sustantivo que describe el acto de escupir, en particular escupir en el rostro de alguien como gesto de extremo desprecio y humillación. Job 17:6 emplea este término metafóricamente: Job se ha convertido en «un escupitajo en la cara», es decir, la gente le escupe como expresión de escarnio. Algunos eruditos han propuesto enmendar el texto para leer «señal» o «portento», pero la lectura masorética encaja bien en el contexto de la degradación social de Job. La imagen es visceral y capta la profundidad de su humillación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8612', 'spa', 'Tofet: un sitio en el Valle de Ben-Hinom al sur de Jerusalén, asociado con el sacrificio de niños y el juicio divino.', 'Nombre propio que identifica un notorio sitio cultual en el Valle de Ben-Hinom (Gehena), justo al sur de Jerusalén, donde se hacía pasar a los niños por el fuego en sacrificio a Moloc. El rey Josías lo profanó durante sus reformas (2 R 23:10), y Jeremías pronunció oráculos devastadores que transformaron su nombre en sinónimo de matanza y cadáveres insepultos (Jer 7:31-32; 19:6-14). Isaías 30:33 imagina una pira al estilo de Tofet preparada para el rey asirio. La etimología sigue siendo debatida, aunque algunos la vinculan con un vocablo arameo para ''hoguera''. El sitio se convirtió en un poderoso símbolo profético de reversión del juicio: el lugar de abominación transformado en lugar de ajuste de cuentas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8613', 'spa', 'Tofet (topónimo; lugar asociado con fuego, usado figuradamente para el juicio divino contra Asiria)', 'En Isaías 30:33 este término aparece como nombre de lugar con vocalización incierta (posiblemente Tofet o Tofteh), empleado metafóricamente para describir el lugar de juicio preparado para el rey de Asiria. El versículo presenta a Tofet como un sitio de incineración dispuesto por el Señor, con fuego y azufre. El nombre está estrechamente emparentado con el Tofet del Valle de Hinom, asociado con el sacrificio de niños. Algunos eruditos consideran que la ה final es una partícula interrogativa unida a la palabra siguiente y no parte del nombre. La imagen evoca destrucción total por fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8615b', 'spa', 'Esperanza, expectativa — anticipación confiada de un resultado futuro, fundada en Dios o en la aspiración humana.', 'Esperanza, expectativa — anticipación confiada de un resultado futuro, fundada en Dios o en la aspiración humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8617', 'spa', 'capacidad de mantenerse firme, poder de resistencia (capacidad de sostener la posición ante un enemigo o amenaza)', 'Este sustantivo designa la capacidad o el poder de mantenerse firme, especialmente frente a la oposición o la amenaza. En Levítico 26:37, aparece en el contexto de una maldición del pacto: si Israel desobedece, no tendrá capacidad de sostenerse ante sus enemigos. Derivado de la raíz קום (levantarse, ponerse en pie), el término enfatiza no solo la postura física sino la capacidad de resistir la derrota y perseverar. El concepto abarca tanto lo físico como lo metafórico, incluyendo valentía, fortaleza y el respaldo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8618', 'spa', 'los que se levantan en contra (participio que describe a quienes se alzan en oposición o rebelión)', 'Forma participial del tronco Hitpolel de la raíz קום (levantarse), que describe a quienes se alzan contra alguien. En el Salmo 139:21, el salmista pregunta retóricamente si no debería aborrecer a los que se levantan contra el Señor, es decir, a los enemigos de Dios que se rebelan o se le oponen. El Hitpolel transmite una acción intensiva o reflexiva, sugiriendo un levantamiento decidido y deliberado. El término aparece en contextos de conflicto y rebelión donde los adversarios se posicionan activamente contra Dios o su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8619', 'spa', 'trompeta, cuerno de carnero (instrumento de señalización; posiblemente infinitivo ''tocar'' en vez de sustantivo)', 'Este término en Ezequiel 7:14 presenta incertidumbre textual. La interpretación tradicional lo toma como sustantivo que significa ''trompeta'' o ''instrumento de toque'' (con la preposición ב: ''con la trompeta''). Sin embargo, la morfología es problemática y muchos eruditos prefieren leer תָּקוֹעַ como un infinitivo absoluto que significa ''tocar'' o ''hacer sonar'', resultando en ''tocan la trompeta'' en lugar de ''tocan con la trompeta''. Ambas lecturas apuntan al mismo campo semántico del toque de trompeta como llamada a la acción militar, en un contexto de alarma bélica desatendida a causa del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8620', 'spa', 'Tecoa: pueblo en las colinas de Judá al sur de Belén, hogar de la mujer sabia y del profeta Amós.', 'Tecoa era un asentamiento en la cima de una colina, a unos ocho kilómetros al sur de Belén, con vistas al desierto que llevaba su nombre. Es conocida sobre todo como la ciudad natal del profeta Amós (Am 1:1) y de la mujer sabia anónima que Joab reclutó para persuadir a David de que permitiera el regreso de Absalón (2 Sam 14:2). Roboam la fortificó como parte de la red defensiva de Judá (2 Cr 11:6), y el ejército de Josafat se congregó en el desierto de Tecoa antes de la derrota milagrosa de Moab y Amón (2 Cr 20:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8621', 'spa', 'Tecoíta, adjetivo gentilicio que designa a una persona oriunda de la ciudad de Tecoa en Judá.', 'Este adjetivo gentilicio identifica a personas procedentes de Tecoa. Aparece tanto en formas masculinas como femeninas: ''el tecoíta'' designa a Ira hijo de Iqués entre los valientes de David (2 Sam 23:26; 1 Cr 11:28; 27:9), mientras que ''la tecoíta'' identifica a la mujer sabia que Joab reclutó (2 Sam 14:4, 9). En Nehemías 3:5 y 27, ''los tecoítas'' son un grupo que ayudó a reconstruir los muros de Jerusalén, aunque sus nobles se negaron a servir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8622', 'spa', 'circuito, ciclo, cumplimiento; el punto de retorno o curso completo de un periodo temporal', 'Este sustantivo designa la culminacion de un ciclo temporal, generalmente el circuito de un ano. La expresion ''a la vuelta del ano'' (Exodo 34:22, 2 Cronicas 24:23) marca las fiestas agricolas en tiempo de cosecha. En 1 Samuel 1:20, describe el cumplimiento de un periodo de gestacion: ''cuando los dias completaron su ciclo,'' Ana dio a luz a Samuel. El Salmo 19:6 lo emplea para el circuito solar completo a traves del cielo, desde el oriente hasta el ocaso, ilustrando el alcance integral de la revelacion de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8623', 'spa', 'el más fuerte, el poderoso (forma comparativa: alguien más fuerte que otro)', 'Este adjetivo, tomado del arameo, significa ''poderoso'' o ''fuerte'', y en Eclesiastés 6:10 aparece en una construcción comparativa con מִן: ''uno más fuerte que él''. El contexto trata sobre la incapacidad humana de contender con quien es más poderoso, refiriéndose probablemente a Dios o al destino. El término es infrecuente en hebreo bíblico pero común en arameo y siríaco, lo que refleja la influencia de estas lenguas cognadas sobre el hebreo bíblico tardío. El sentido comparativo es esencial: no simplemente fuerte, sino más fuerte que el ser humano que intenta argumentar o contender.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8624', 'spa', 'Fuerte, poderoso, imponente; aplicado a reinos, bestias temibles y prodigios divinos (arameo)', 'Este adjetivo arameo תַּקִּיף describe una fuerza formidable en Daniel y Esdras. En Daniel 2:40 y 2:42 caracteriza al reino semejante al hierro en el sueño de Nabucodonosor. Daniel 7:7 lo aplica a la espantosa cuarta bestia, mientras que Daniel 4:3 lo atribuye a los prodigios poderosos de Dios. Esdras 4:20 señala que Jerusalén tuvo en otro tiempo ''reyes poderosos'' que gobernaban más allá del río. La palabra siempre conlleva matices de dominio y poder que infunde reverencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8625a', 'spa', 'has sido pesado (verbo arameo; examinado y evaluado, como en una balanza)', 'Este verbo arameo aparece en Daniel 5:27, en la célebre escena de la escritura en la pared, donde Daniel interpreta el mensaje críptico dirigido a Belsasar: ''TEKEL: has sido pesado en la balanza y hallado falto''. La raíz תקל corresponde al hebreo שָׁקַל (pesar), y la forma pasiva indica que Belsasar ha sido sometido a una evaluación divina. La imagen de pesar evoca un juicio donde el valor o la rectitud de una persona se mide como en una balanza, conduciendo al veredicto: ''hallado falto'', es decir, deficiente e insuficiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8626', 'spa', 'enderezar, poner en orden, corregir lo torcido o desordenado', 'Este verbo denota la acción de enderezar, arreglar o poner en el orden apropiado. Cohélet lo usa para explorar las preguntas fundamentales de la vida: lo torcido no se puede enderezar (1:15), y ¿quién puede enderezar lo que Dios ha torcido? (7:13). Sin embargo, en 12:9, el Predicador mismo ''ordenó'' proverbios, dando estructura a la sabiduría. La palabra lleva dimensiones tanto cósmicas como prácticas: reconoce los límites del poder humano para arreglar las distorsiones de la creación mientras afirma nuestra capacidad de ordenar la sabiduría y el conocimiento. Se trata de alineación, corrección, arreglo apropiado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8627', 'spa', 'Fui restablecido, restaurado (arameo Hofal: devuelto al orden o posición debida)', 'Este verbo arameo en la conjugación Hofal aparece en Daniel 4:36, donde Nabucodonosor testifica que, tras su período de locura y humillación, fue «restablecido» sobre su reino. La raíz תקן significa «estar en orden» o «disponer», y en el Hofal pasivo indica ser restaurado o reinstaurado. El contexto es de restauración tras el juicio divino: la razón de Nabucodonosor regresa y es restituido a su trono. El verbo transmite tanto restauración mental (cordura) como restauración política (realeza).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8628', 'spa', 'Clavar, hundir, tocar (una trompeta), batir (palmas), dar la mano (en prenda) — impacto físico que produce sonido o asegura un objeto. תָּקַע es un ve', 'Clavar, hundir, tocar (una trompeta), batir (palmas), dar la mano (en prenda) — impacto físico que produce sonido o asegura un objeto. תָּקַע es un verbo vívido y físico cuyo significado central es una acción contundente de golpe o empuje. Su uso más frecuente — tocar una trompeta o shofar — representa casi el 70% de las apariciones y domina el paisaje sonoro de la narrativa bíblica, desde la caída de Jericó (Jos 6:4-20) hasta la incursión nocturna de Gedeón (Jue 7:18-22). Pero la misma raíz describe a Jael clavando una estaca de tienda en la sien de Sísara (Jue 4:21), a Joab hundiendo dardos en el corazón de Absalón (2 S 18:14), y a la persona imprudente que ''da la mano'' en una garantía financiera (Pr 6:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8629', 'spa', 'Toque de cuerno, sonido de trompeta (el sonido producido al soplar un cuerno de carnero o trompeta)', 'Este sustantivo designa el toque o sonido producido al soplar un cuerno o trompeta (שׁוֹפָר). El Salmo 150:3 exhorta a alabar a Dios «con sonido de trompeta», es decir, con el toque del cuerno de carnero. El término deriva de la raíz תָּקַע (clavar, golpear, soplar un cuerno), y la forma constructa enfatiza el sonido característico del instrumento, no el instrumento mismo. En el culto de Israel, el toque del shofar cumplía funciones tanto litúrgicas (fiestas, adoración) como militares (alarma, convocación). El término se centra en el fenómeno auditivo: el sonido penetrante y resonante que reclama atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8630', 'spa', 'dominar, prevalecer contra, vencer por la fuerza', 'Verbo del hebreo tardio, probablemente un aramaismo, que aparece en la literatura sapiencial. Eclesiastes lo usa dos veces: para describir como alguien domina a una persona sola (4:12) y la imposibilidad de que un mortal prevalezca contra uno mas fuerte (6:10, lectura ketiv). Job lo emplea para expresar el dominio abrumador de Dios: ''Tu prevaleces para siempre contra el'' (14:20, 15:24). El campo semantico gira en torno a la fuerza superior que somete a una oposicion mas debil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8631', 'spa', 'Hacerse fuerte, llegar a ser poderoso; en Pael, imponer o hacer riguroso (arameo)', 'El verbo arameo תְּקֵף describe el proceso de volverse poderoso o endurecerse. En Daniel 4, el gran árbol ''se hizo fuerte'' (4:11, 20), reflejando la expansión del dominio de Nabucodonosor, y al propio rey se le dice ''te has hecho fuerte'' (4:22). Un matiz más sombrío emerge en 5:20, donde la arrogancia endurecida conduce a la caída. El tallo Pael en 6:7 adquiere un sentido causativo: ''imponer'' o hacer vinculante un decreto. El español capta ambos polos: ''se hizo fuerte'' y ''para imponer''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8632a', 'spa', 'Poder, fuerza (sustantivo arameo que denota capacidad vigorosa o poderío)', 'Sustantivo arameo que significa «poder» o «fuerza», que aparece en Daniel 4:30 en la declaración jactanciosa de Nabucodonosor sobre su propio poderío: «con la fuerza de mi poder». El término enfatiza la capacidad enérgica, la aptitud para realizar grandes obras mediante la fuerza. En el contexto inmediato, Nabucodonosor atribuye sus logros constructivos a su propio poder, lo cual prepara la reprensión divina que sigue. La palabra aparece en forma constructa, unida a «mi fuerza», creando una expresión intensificada de poder autosuficiente, que contrasta con el tema de la soberanía de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8632b', 'spa', 'La fuerza, el poderío (forma enfática aramea; poder o dominio definido)', 'Sustantivo arameo en forma enfática (definida) que significa «la fuerza» o «el poderío». En Daniel 2:37, Daniel le dice a Nabucodonosor que el Dios del cielo le ha dado «el reino, el poder, la fuerza y la gloria». La terminación enfática -א funciona como el artículo definido hebreo, especificando «la fuerza (particular)» que Dios ha concedido. El término aparece en una serie de atributos reales —soberanía, poder, fuerza, gloria— todos atribuidos a la concesión divina y no al logro humano. Este enfoque teológico contrasta con la soberbia posterior del rey en Daniel 4.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8633', 'spa', 'poder, fuerza, poderío, especialmente en contextos reales o imperiales', 'Este sustantivo denota poder y fuerza, particularmente como los ejercen gobernantes y reinos. En Ester, describe el poder autoritativo con el que escribe la reina Ester (9:29) y los actos poderosos del rey Asuero (10:2), emparejado con ''poder'' (gevurah) para enfatizar la fuerza real. Daniel lo usa para ''la fuerza de todo su reino'', refiriéndose al poder imperial ejercido en acción política. El término a menudo aparece en contextos de decretos oficiales, actos reales y poderío político. Sugiere no meramente fuerza abstracta, sino poder activamente desplegado, autoridad ejercida con vigor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8634', 'spa', 'Taralá (nombre de lugar; ciudad en el territorio tribal de Benjamín, Josué 18:27)', 'Nombre de una ciudad que aparece en la lista de límites de la herencia de Benjamín. Josué 18:27 sitúa a Taralá entre las ciudades asignadas a la tribu de Benjamín en la región montañosa central. Su ubicación no ha sido identificada con certeza en la geografía moderna, aunque era claramente conocida en la antigüedad. La Septuaginta la transcribe como Θαρεηλα o Θεραλα, con ligeras variaciones en la vocalización griega. Como muchos nombres de ciudades en las listas de repartición tribal, Taralá sirve principalmente como referente geográfico en la distribución de la tierra de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8635', 'spa', 'cría de, prole de (término despectivo para descendientes o progenie que perpetúan el pecado de sus padres)', 'Este sustantivo significa ''aumento'' o ''cría'', pero en Números 32:14 lleva un tono marcadamente despectivo. Moisés reprende a los rubenitas y gaditas llamándolos ''cría de hombres pecadores'', es decir, progenie que ha heredado y perpetúa la pecaminosidad de sus antepasados. El término deriva de una raíz que significa ''aumentar'' o ''multiplicar'', pero en este contexto no enfatiza la cantidad sino la calidad: son un aumento del mal, una proliferación de rebeldía. La fuerza despectiva proviene de llamar ''cría'' a hombres adultos, como si solo estuvieran engendrando más pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8636', 'spa', 'Aumento, interés o ganancia usuraria obtenida mediante préstamos; aparece constantemente junto a neshekh en prohibiciones legales.', 'Este sustantivo designa el incremento financiero o la ganancia extraída de un préstamo, y aparece casi siempre junto a neshekh (''interés'' o ''mordedura''). Ambos términos forman una hendíadis que abarca toda forma de préstamo abusivo. La Torá prohíbe ambos tajantemente (Lv 25:36), los profetas los condenan como indicadores de injusticia social (Ez 18:8, 13, 17; 22:12), y Proverbios advierte que la riqueza acumulada mediante usura terminará en manos del generoso (Pr 28:8). El cognado árabe riba, aún vigente en las finanzas islámicas, comparte la misma raíz semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8637', 'spa', 'enseñar a caminar, adiestrar en los primeros pasos (como un padre guiando a un niño pequeño)', 'Este verbo denominativo derivado de la raíz רגל (pie) aparece en Oseas 11:3, donde Dios recuerda con ternura haber enseñado a Efraín a caminar, como un padre que guía los primeros pasos de un niño. La forma verbal (Tifael o Pilpel) sugiere acción intensiva o causativa: no simplemente caminar, sino ser adiestrado a caminar mediante práctica repetida. La imagen es profundamente íntima: Dios como padre que se inclina para guiar los pasos vacilantes de Israel. Sin embargo, el pathos radica en que Israel no reconoció quién le estaba enseñando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8638', 'spa', 'traducido, interpretado (participio pasivo arameo; vertido de una lengua a otra)', 'Este verbo cuadriliteral arameo significa ''interpretar'' o ''traducir'', y aparece en Esdras 4:7 como participio pasivo describiendo una carta que fue ''traducida'' al arameo. La raíz תרגם es el origen del término ''Targum'', las traducciones-paráfrasis arameas de la Biblia hebrea. El verbo denota verter un discurso o escrito de una lengua a otra, haciéndolo inteligible para un público diferente. En el contexto de Esdras, los funcionarios persas enviaron una carta en escritura y lengua aramea, es decir, ''traducida'' a la lengua administrativa imperial. El término tiene cognados en asirio (targumānu, intérprete) y en árabe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8639', 'spa', 'Sueño profundo y sobrenatural enviado por Dios, que produce insensibilidad semejante al trance; distinto del sueño ordinario.', 'A diferencia del sueño común, tardemah describe una inconsciencia profunda inducida divinamente. Dios la hizo caer sobre Adán antes de crear a Eva (Gn 2:21), sobre Abram durante el pacto de las piezas (Gn 15:12) y sobre el campamento de Saúl para que David pudiera acercarse sin ser detectado (1 Sam 26:12). En Job 4:13 y 33:15 es el estado en que Dios se comunica mediante visiones. Isaías 29:10 la emplea metafóricamente como un ''espíritu de sueño profundo'' derramado para describir la insensibilidad espiritual. La Septuaginta la traduce como ekstasis (''trance'') y thambos (''asombro''), reflejando su carácter sobrenatural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8641', 'spa', 'Contribución u ofrenda separada para uso sagrado; la porción elevada o apartada para Dios, los sacerdotes o el santuario. תְּרוּמָה designa algo delib', 'Contribución u ofrenda separada para uso sagrado; la porción elevada o apartada para Dios, los sacerdotes o el santuario. תְּרוּמָה designa algo deliberadamente separado del todo y elevado como don a Dios. En su uso más amplio cubre cualquier contribución voluntaria traída con propósitos sagrados: el oro, la plata y los tejidos donados para la construcción del tabernáculo (Éx 25:2-3) o las primicias agrícolas presentadas en el santuario (Dt 12:6). Más técnicamente, se refiere a la porción del sacerdote físicamente elevada del sacrificio o la cosecha y apartada como su derecho (Éx 29:27-28). En una aparición inusual (Pr 29:4), parece significar exacciones o sobornos que arruinan una nación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8642', 'spa', 'contribución, ofrenda (porción secundaria o subdivisión apartada como sagrada)', 'Este sustantivo denominativo deriva de תְּרוּמָה (contribución, ofrenda elevada) y designa algo que pertenece o está asociado a una contribución, una especie de ofrenda secundaria o complementaria. La forma funciona adjetivamente (sustantivada), significando ''lo que pertenece a una contribución''. En Ezequiel 48:12 describe una franja de tierra destinada a los sacerdotes dentro del esquema visionario del templo de Ezequiel. No obstante, BDB sugiere que el texto probablemente esté corrupto y debería leerse simplemente תְּרוּמָה. El campo semántico permanece en el dominio de las contribuciones sagradas y porciones apartadas para uso sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8643', 'spa', 'Grito o toque de trompeta — grito de guerra, señal de alarma o aclamación jubilosa ante Dios.', 'Grito o toque de trompeta — grito de guerra, señal de alarma o aclamación jubilosa ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8644', 'spa', 'sanidad, remedio (función restauradora o curativa, propósito medicinal)', 'Este sustantivo denota sanidad o cura, y aparece en Ezequiel 47:12 en la visión del río que fluye del templo. Las hojas de los árboles a lo largo de este río se describen como destinadas ''para sanidad'', es decir, poseen propiedades medicinales o restauradoras. El término deriva de una raíz que significa ''sanar'' o ''curar'', y el contexto es escatológico: en la creación renovada que fluye de la presencia de Dios, hasta la vegetación cumple propósitos terapéuticos. Esta imagen anticipa Apocalipsis 22:2, donde las hojas del árbol de la vida son ''para la sanidad de las naciones''. La imagen transmite restauración y plenitud integrales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8645', 'spa', 'ciprés o encina (especie arbórea incierta, posiblemente ciprés u olmo; madera usada para tallar ídolos)', 'Nombre de un árbol de identificación incierta que aparece únicamente en Isaías 44:14. Se ha traducido tradicionalmente como ''ciprés'' o ''encina'', aunque la especie exacta sigue siendo objeto de debate. El contexto enumera este árbol junto con cedros y robles como madera empleada para fabricar ídolos: el profeta satiriza a quienes usan la misma madera para calentarse, hornear pan y tallar dioses. Claramente se trata de una madera dura y resistente, apta para el tallado. La Vulgata lee ''ilex'' (encina). Lo esencial no es la especie botánica sino su uso indebido como materia prima para la idolatría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8646', 'spa', 'Téraj — padre de Abraham y patriarca de la migración de Ur a Harán; también un campamento en el desierto en la ruta del Éxodo. Principalmente el nombr', 'Téraj — padre de Abraham y patriarca de la migración de Ur a Harán; también un campamento en el desierto en la ruta del Éxodo. Principalmente el nombre del padre de Abraham, hijo de Nacor, quien inició la partida de la familia desde Ur de los caldeos hacia Canaán, pero se estableció en Harán, donde murió a los 205 años (Gn 11:24-32). Josué 24:2 lo recuerda como uno que sirvió a otros dioses al otro lado del Éufrates — una nota llamativa de idolatría en el linaje patriarcal. El hilo genealógico se extiende a través de 1 Crónicas 1:26. Un segundo Téraj, menos prominente, es un campamento israelita durante las peregrinaciones por el desierto (Nm 33:27-28). La etimología podría estar relacionada con una palabra acadia para íbice o un nombre divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8647', 'spa', 'Tirjaná (nombre propio; descendiente de Caleb en la genealogía de Judá, 1 Crónicas 2:48)', 'Nombre propio que aparece en 1 Crónicas 2:48 dentro de la genealogía de Caleb. Tirjaná fue hijo o hija de Caleb y su concubina Maaca; el género es incierto. El nombre se menciona una sola vez en las Escrituras y su etimología permanece oscura. La Septuaginta ofrece transliteraciones variadas (Θαραμ, Θαρχνα, Θαραανα), lo que evidencia la dificultad que este nombre poco común representaba para los traductores antiguos. Como muchos nombres genealógicos, su función principal es documentar el linaje familiar de los clanes calebitas, más que transmitir un significado semántico particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8648', 'spa', 'dos (numeral arameo); masculino תְּרֵין, femenino תַּרְתֵּין', 'El numeral arameo ''dos,'' que aparece en Daniel y Esdras. Se combina con ''diez'' para formar ''doce'' (Esdras 6:17, Daniel 4:26). Daniel 5:31 registra que Dario el medo recibio el reino ''siendo de unos sesenta y dos anos.'' Esdras 4:24 fecha los acontecimientos en ''el segundo ano'' de Dario. Como otros numerales arameos, muestra concordancia de genero tipica de las lenguas semiticas: forma masculina con sustantivos masculinos y femenina con femeninos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8649', 'spa', 'engaño, fraude (representación fraudulenta, especialmente en la falsa profecía)', 'Este sustantivo designa el engaño, la falsedad o la representación fraudulenta. En Jeremías 14:14, Dios condena a los falsos profetas que profetizan ''el engaño de su propio corazón'', es decir, mentiras autogeneradas que atribuyen fraudulentamente a la revelación divina. El término subraya la naturaleza deliberada del engaño, particularmente en el contexto de la falsa profecía. La raíz sugiere astucia y manipulación, y su uso aquí resalta la culpabilidad moral de quienes reclaman autoridad divina para sus propias invenciones. No se trata de un simple error, sino de un fraude voluntario, especialmente peligroso cuando se reviste de autoridad religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8649a', 'spa', 'con engaño, traidoramente (texto posiblemente corrupto; lectura alternativa: ''a Arumá'' como topónimo)', 'Este término en Jueces 9:31 presenta un problema textual. El texto masorético lee בְּתָרְמָה, que podría significar ''con engaño'' o ''traidoramente'', pero la forma es inusual y el sentido resulta forzado en su contexto. Muchos estudiosos proponen enmendar a בַּאֲרוּמָה, entendiendo esto como el topónimo Arumá mencionado en el versículo 41. Si se conserva como ''con engaño'', describiría a los mensajeros acudiendo en secreto o traidoramente para advertir a Abimelec. La incertidumbre se refleja en las traducciones: algunas lo tratan como nombre de lugar (''en Torma''), mientras otras preservan el sentido masorético. Es probable que el texto haya sufrido una corrupción temprana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8649b', 'spa', 'Engaño, perfidia; cualidad de falsedad arraigada, especialmente en la falsa profecía y los corazones infieles', 'תַּרְמִית designa un engaño profundamente arraigado: la perfidia que anida en el corazón humano y en la lengua. Jeremías la emplea para diagnosticar la enfermedad espiritual de Israel: el pueblo se aferra a un ''engaño perpetuo'' (8:5) y los falsos profetas hablan desde ''el engaño de su propio corazón'' (14:14; 23:26). El salmista en 119:118 desecha a quienes cuya falsedad (שֶׁקֶר) es en sí misma engañosa (תַּרְמִית). Sofonías 3:13 vislumbra un remanente purificado cuya lengua no alberga engaño alguno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8650', 'spa', 'mástil de barco, o metafóricamente un poste solitario o estandarte', 'Este sustantivo denota principalmente el mástil de un barco: el poste alto que sostiene las velas. Ezequiel 27:5 lo usa al describir el barco de Tiro como embarcación magnífica con su mástil. Isaías emplea la imagen metafóricamente: un poste de señal en la cima de un monte (30:17) o un asta de bandera (33:23), ambos sugiriendo algo solitario y prominente. La comparación retrata a Israel reducido al aislamiento como un poste solitario en donde antes había un bosque. La palabra se mueve de la terminología náutica literal a imagen poética de desolación y visibilidad: algo que permanece solo, expuesto, ya sea para señalizar o como remanente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8652', 'spa', 'porteros, guardianes de las puertas (arameo; personal del templo encargado de custodiar las entradas)', 'Sustantivo plural arameo que designa a los porteros o guardianes de las puertas, específicamente al personal del templo responsable de custodiar los accesos. En Esdras 7:24, este término aparece en el decreto de Artajerjes que exime de impuestos al personal del templo, incluyendo sacerdotes, levitas, cantores, porteros y sirvientes del templo. Los porteros constituían una clase diferenciada de funcionarios sagrados, encargados de controlar el acceso al espacio consagrado. La forma aramea aparece en plural enfático, funcionando de manera similar al artículo definido en hebreo. Este personal era esencial para mantener los límites entre lo sagrado y lo profano en el Segundo Templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8653', 'spa', 'tambaleo, aturdimiento, la desorientación causada por juicio divino o embriaguez', 'Este sustantivo capta la desorientación física y espiritual del tambaleo: la pérdida de equilibrio bajo juicio divino. Isaías habla de ''la copa del aturdimiento'' (51:17, 22), potente imagen de la ira de Dios que hace que la gente tambalee como ebrios, despojados de estabilidad y claridad. El salmista describe a Dios dando a Su pueblo ''vino de tambaleo'' para beber (60:3): juicio que desorienta y abruma. La palabra transmite más que tropiezo físico; sugiere la profunda desorientación que viene cuando la mano de Dios presiona en disciplina, dejando a la gente incapaz de encontrar su equilibrio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8654', 'spa', 'tirateos (nombre de familia; clan quenita descendiente de escribas, 1 Cronicas 2:55)', 'Nombre de familia o clan que aparece en 1 Cronicas 2:55, designando a una de las tres familias de escribas que habitaban en Jabes. Los tirateos eran quenitas, descendientes de Hamat, padre de la casa de Recab. El nombre esta en plural, indicando un grupo familiar y no un individuo. Los quenitas fueron tradicionalmente aliados de Israel, y este pasaje sugiere que entre ellos habia familias dedicadas a la labor escribal. La Septuaginta traduce el nombre como Θαργαθυμ. El termino funciona como designacion de clan, marcando la identidad ancestral y la especializacion profesional del grupo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8655', 'spa', 'Terafines — figurillas de ídolos domésticos utilizadas para la adivinación y el culto familiar. Los תְּרָפִים (terafines) son figurillas de ídolos dom', 'Terafines — figurillas de ídolos domésticos utilizadas para la adivinación y el culto familiar. Los תְּרָפִים (terafines) son figurillas de ídolos domésticos cuya naturaleza exacta sigue siendo debatida. Raquel robó famosamente los terafines de su padre Labán (Gn 31:19, 34-35), donde se los llama ''dioses'' (elohim). Mical usó uno para simular la forma dormida de David, lo que sugiere una figura de tamaño natural (1 S 19:13, 16). Aparecen junto a efods en santuarios privados (Jue 17:5; 18:14-20) y figuran entre objetos adivinatorios condenados (1 S 15:23; 2 R 23:24; Zac 10:2). Oseas 3:4 los empareja con elementos cúlticos legítimos como cosas que Israel perderá. La etimología permanece incierta, aunque algunos la conectan con רפא (espíritus sanadores).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8656', 'spa', 'Tirsa — nombre propio que significa ''placer, belleza'', llevado por una hija de Zelofehad y una antigua capital israelita.', 'Tirsa — nombre propio que significa ''placer, belleza'', llevado por una hija de Zelofehad y una antigua capital israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8658', 'spa', 'Piedra preciosa de color amarillo verdoso, probablemente crisólito o berilo; presente en vestiduras sacerdotales y visiones teofánicas.', 'Este nombre de gema designa una piedra lustrosa de tonalidad dorada, engastada en la cuarta fila del pectoral del sumo sacerdote (Éx 28:20; 39:13) y usada para describir el resplandor de figuras divinas y regias. La visión de Ezequiel de los seres vivientes incluye ruedas ''con apariencia de piedra de Tarsis'' (1:16; 10:9), y el visitante angélico de Daniel tiene un cuerpo ''como Tarsis'' (10:6). En el Cantar de los Cantares, las manos del amado se comparan con cilindros de oro engastados con Tarsis (5:14). La Septuaginta lo traduce como chrysolithos (''piedra de oro''), apuntando a una gema dorada o verde dorada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8659', 'spa', 'Tarsis — un puerto marítimo distante que simboliza el comercio ultramarino lejano, frecuentemente identificado con Tartesos en España', 'Tarsis — un puerto marítimo distante que simboliza el comercio ultramarino lejano, frecuentemente identificado con Tartesos en España');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8660', 'spa', 'Tirsata; título del gobernador de Judá designado por Persia, equivalente a ''Su Excelencia'' o ''el venerado''', 'Tirsata es un préstamo del persa usado como título honorífico para el gobernador de Judá en el periodo postexílico. Aparece en Esdras 2:63 y Nehemías 7:65 referido a un gobernador sin nombre que restringe privilegios sacerdotales hasta que se consulten el Urim y el Tumim, y en Nehemías 8:9 y 10:1 designa explícitamente a Nehemías mismo. El título probablemente deriva de una raíz persa que significa ''temido, venerado'', funcionando de modo análogo a ''Su Excelencia'' en el uso diplomático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8662', 'spa', 'Tartac (nombre divino; deidad adorada por los aveos, 2 Reyes 17:31)', 'Nombre divino que aparece en 2 Reyes 17:31, designando a una deidad adorada por los aveos, uno de los pueblos extranjeros asentados en Samaria tras la conquista asiria. Junto con Nibhaz, Tartac era uno de los dioses que los aveos trajeron consigo y continuaron adorando en su nueva tierra. El nombre no ha sido identificado de manera satisfactoria con ninguna deidad conocida de fuentes del antiguo Cercano Oriente, y su etimologia sigue siendo incierta. La Septuaginta lo transcribe como Θαρθακ. El termino aparece en el contexto de un culto sincretista que mezclaba el yahvismo con deidades extranjeras, practica que el texto biblico condena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8663', 'spa', 'ruido, clamor, tumulto; estruendo de multitudes o fragor de tormenta', 'Sustantivo plural que designa sonidos fuertes y caóticos, ya sean humanos o naturales. Isaías 22:2 describe a Jerusalén como una ciudad «llena de alboroto», un bullicio urbano tumultuoso. Zacarías 4:7 imagina la piedra angular del templo colocada entre «aclamaciones» de júbilo. Job lo emplea para el estruendo atronador de la tormenta divina (36:29) y señala que el asno montés no escucha los «gritos» del capataz (39:7). Un pasaje (Job 30:22, ketiv) podría aludir al rugido de la tempestad en la que Job se disuelve.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8664', 'spa', 'Tisbita; adjetivo gentilicio que identifica a Elías como oriundo de Tisbe en Galaad.', 'Designación gentilicia que significa ''el tisbita'', empleada exclusivamente para identificar al profeta Elías. El término aparece seis veces en los libros de Reyes, siempre en la fórmula ''Elías el tisbita'' (1 Re 17:1; 21:17, 28; 2 Re 1:3, 8; 9:36). Las traducciones en diversas lenguas son llamativamente uniformes: español ''el tisbita'', francés ''le Tishbite'', inglés ''the Tishbite'', todas simplemente transliterando el gentilicio. La localidad de Tisbe se ubica tradicionalmente en Galaad, al este del Jordán, enraizando al fogoso profeta en las agrestes tierras altas de Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8665', 'spa', 'labor a cuadros, bordado o trenzado (tejido con diseño ornamental)', 'Este sustantivo describe un tipo de labor textil: tela a cuadros, trenzada o bordada. En Éxodo 28:4 aparece en la expresión «túnica a cuadros», como una de las vestiduras sacerdotales. El término sugiere una técnica decorativa de tejido que produce textura o diseño visual, distinguiendo esta prenda de la tela lisa. La técnica exacta es incierta —¿cuadros tejidos?, ¿bordados?, ¿trenzado?—, pero el resultado es claramente ornamental. Esto refleja la belleza y dignidad propias del servicio sagrado, donde el vestuario sacerdotal combinaba función con esplendor simbólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8666', 'spa', 'Retorno, punto de inflexión (especialmente de una estación o año); también respuesta o réplica en el discurso.', 'Sustantivo femenino de la raíz shuv (''volver'') que presenta dos sentidos diferenciados. Con mayor frecuencia funciona como marcador temporal — ''al retorno del año'' — designando la temporada de campañas primaverales cuando los reyes salían a la guerra (2 Sam 11:1; 1 R 20:22, 26; 1 Cr 20:1). Este es el fatídico cambio de año en que David se quedó en casa y vio a Betsabé. En la literatura sapiencial se desplaza al significado de réplica o respuesta verbal, como cuando Elihú evalúa las ''respuestas'' de Job como contenedoras de maldad (Job 34:36) y Job impugna las vacías ''réplicas'' de sus amigos (21:34).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8667', 'spa', 'prenda, depósito (algo confiado a otro como garantía o custodia)', 'Este sustantivo designa una prenda, depósito o bien confiado a otro para su custodia. En Levítico 6:2 (5:21 en la numeración española) aparece en un contexto legal sobre el engaño: si alguien miente acerca de un depósito que le fue confiado, negando haberlo recibido, comete fraude y debe restituirlo. El término es paralelo a פִּקָּדוֹן (depósito, cosa confiada) y subraya la responsabilidad fiduciaria. La forma constructa תְּשׂוּמֶת יָד (literalmente «depósito de mano») sugiere algo puesto en manos de alguien para su resguardo. Violar esta confianza transgrede tanto la ética interpersonal como la ley del pacto, exigiendo ofrenda por la culpa y restitución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8668', 'spa', 'Liberación, salvación o victoria; los actos salvíficos de Dios, desde el rescate en batalla hasta la redención espiritual integral.', 'Liberación, salvación o victoria; los actos salvíficos de Dios, desde el rescate en batalla hasta la redención espiritual integral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8669', 'spa', 'deseo, anhelo, atracción magnética de una persona o cosa hacia otra', 'Este sustantivo poco común denota un anhelo o deseo profundo que atrae a un ser hacia otro. En Génesis 3:16, describe el deseo de la mujer hacia su esposo a pesar del dolor del parto—una atracción compleja en las consecuencias de la caída. Génesis 4:7 lo usa para el deseo del pecado de dominar a Caín, personificando el hambre acechante del pecado. El Cantar de los Cantares invierte el lenguaje de Génesis 3: ''Yo soy de mi amado, y su deseo es para mí'' (7:10)—anhelo mutuo redimido. La palabra captura una atracción magnética, ya sea entre personas enamoradas, de la mujer hacia el hombre bajo maldición, o del mal hacia su presa. Es deseo que se extiende, que quiere poseer o ser poseído.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8670', 'spa', 'regalo, presente (algo traído u ofrecido, posiblemente como pago o tributo)', 'Este sustantivo aparece únicamente en 1 Samuel 9:7 y probablemente significa «regalo» o «presente», aunque su etimología y significado exacto son inciertos. Saúl y su criado, al buscar al vidente Samuel, se dan cuenta de que no tienen un regalo que llevarle: el pan se ha acabado y carecen de un «presente» que ofrecerle. El contexto sugiere una ofrenda o pago acostumbrado al consultar a un profeta, en reconocimiento de su servicio. El término podría derivar de una raíz que significa «traer» u «ofrecer», es decir, «cosa traída». El BDB señala que el significado se infiere del contexto más que de una etimología establecida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8671', 'spa', 'El noveno — número ordinal que marca la novena posición en una secuencia de tiempo, personas u objetos.', 'El noveno — número ordinal que marca la novena posición en una secuencia de tiempo, personas u objetos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8672', 'spa', 'Nueve (numeral cardinal); en fórmulas temporales con בְּ, noveno (sentido ordinal). El numeral cardinal hebreo nueve, que aparece a lo largo de geneal', 'Nueve (numeral cardinal); en fórmulas temporales con בְּ, noveno (sentido ordinal). El numeral cardinal hebreo nueve, que aparece a lo largo de genealogías, censos, medidas y fórmulas de fecha. Se presenta en formas tanto masculina (תִּשְׁעָה) como femenina (תֵּשַׁע) y se combina libremente con decenas y centenas (diecinueve, veintinueve, novecientos). Cuando va precedido de la preposición בְּ en fórmulas de fecha, funciona como ordinal: ''en el noveno.'' Las genealogías de Génesis 5 lo usan reiteradamente para las edades de los patriarcas, mientras que las fórmulas de datación profética en Jeremías y 2 Reyes marcan momentos decisivos como la caída de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8673', 'spa', 'Noventa — el número cardinal 90, usado en edades, medidas y conteos a lo largo del AT.', 'Noventa — el número cardinal 90, usado en edades, medidas y conteos a lo largo del AT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8674', 'spa', 'Tatnai, funcionario persa; gobernador de la provincia de Más Allá del Río bajo Darío I', 'Nombre propio que designa al prefecto persa que gobernaba la región del Trans-Éufrates (Siria-Palestina) durante los primeros años del reinado de Darío I. Tatnai investigó la reconstrucción del templo de Jerusalén y se correspondió con la corte persa acerca de la autorización de los judíos (Esdras 5:3, 6; 6:6, 13). Tablillas cuneiformes contemporáneas confirman la existencia de un personaje similar —Uštanni o Uštanu— como prefecto de esa región, lo que sugiere su identificación textual con este personaje bíblico.');